window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]=window.__LIBQ["the-gioi-hoan-my"]["q10"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]["cotTruyen"]=[{"chuong":901,"tieuDe":"Sóng Lớn Cuộn Trào","tomTat":"Thạch Hạo dùng đoạn tiên thể làm điều kiện trao đổi và được Tuyết Lâm cho biết Cung điện Chí tôn từng do một con rùa khổng lồ cõng xuyên qua vách ngăn hai giới. Cổ tổ của nàng đã lần theo dấu vết tới sâu trong khu không người và suy đoán cung điện đang hướng về Cổ thành Minh Ước, khiến Thạch Hạo quyết tâm tương lai sẽ tới đó tìm hiểu. Nhóm Thạch Hạo dựng trận pháp quanh đoạn tiên thể để hấp thu khí tức Tiên đạo; riêng hắn bồi dưỡng tia tiên khí thứ nhất đến đại viên mãn, còn những người khác chủ yếu được tẩm bổ thân thể. Khi kết thúc bế quan, Thạch Hạo giao đoạn tiên thể cho Tào Vũ Sinh, để Thái Âm Ngọc Thỏ tiếp tục đi cùng và mang số bảo dược của mình. Hắn trở lại ba ngàn đường đá, đồng thời đốt cháy ba ngàn ngọn lửa nhưng cuối cùng xác định nơi này không thể giúp mình tu ra tia tiên khí thứ hai. Trong lúc đó, Đệ nhất Liệp sát giả của Thiên quốc báo cáo về Hoang cho quái thai cổ đại, Hắc Ám Thần tử ra lệnh cho Minh thổ tham gia truy sát, còn Quân Đạo tuyên bố sẽ báo thù cho Đọa Thần tử. Nhiều lực lượng cùng lúc chuyển động khiến Hoang đứng trước nguy cơ bị vây giết trên quy mô lớn."},{"chuong":902,"tieuDe":"Lạnh Lẽo","tomTat":"Thạch Hạo kết thúc thời gian bế quan trên Ba ngàn đường đá sau khi tu thành luồng tiên khí đầu tiên. Hắn cùng Đả Thần Thạch dựng tượng giả và bố trí sát trận, ẩn trận cùng mê trận để đối phó những kẻ mang địch ý truy tìm mình. Sau đó Thạch Hạo dẫn Thái Âm Ngọc Thỏ, Đả Thần Thạch và Hoàng điệp tiến vào Hàn giới để chuẩn bị tu luồng tiên khí thứ hai. Trong vùng núi tuyết, họ chứng kiến nhiều thần linh và cả một bộ lạc sừng kỳ lân bị đông chết trong khoảnh khắc. Tiên kiếm Đại La phát sáng, khiến núi tuyết dâng mưa ánh sáng và làm luồng tiên khí của Thạch Hạo cộng hưởng với khí tức Tiên đạo. Trong khi đó, Minh tộc, Thiên quốc, người giúp sức cho Quân Đạo cùng nhiều cao thủ tập trung tại Ba ngàn đường đá để săn giết Hoang."},{"chuong":903,"tieuDe":"Muốn Thành Tiên","tomTat":"Hắc Ám Thần tử, Quân Đạo, Quái thai cổ đại của Thiên quốc cùng nhiều trận doanh tập hợp trên ba ngàn đường đá để vây giết Hoang. Liên quân bị tiếng nói, khí huyết và hơi thở lưu trong tượng giả đánh lừa, tiếp tục tiến công bất chấp trận pháp phản kích và gây thương vong lớn. Thạch Hạo thực ra đang ở sâu trong Hàn giới cùng Thái Âm Ngọc Thỏ và Đả Thần Thạch, nơi một tế đàn cổ phát ra mưa sáng phi tiên cùng luồng khí lạnh chí âm chí cường. Khi dùng Tiên kiếm Đại La và hai mảnh Vạn Linh đồ thăm dò, hắn nhìn thấy dấu ấn của một người trung niên có uy thế không kém Diệp Thiên Vũ và nghe lời tuyên bố muốn thành Tiên. Trên ba ngàn đường đá, trận pháp bất ngờ khép lưới, cuốn lực lượng thảo phạt vào tuyệt trận; Quân Đạo nhìn thấu tượng giả nhưng phải thiêu đốt bí bảo và trọng thương gần chết mới thoát. Hắc Ám Thần tử dựa vào thể phách cùng bảo thuật tự phát mở được đường sống, còn Quái thai cổ đại của Thiên quốc không nhập trận nên bình an và tuyên bố sẽ tuyệt sát Hoang. Việc nhiều cánh quân gần như bị diệt sạch khiến các tiểu thiên thế giới trong Tiên cổ và những đại giáo ngoài ngoại giới đồng loạt chấn động."},{"chuong":904,"tieuDe":"Nguyền Rủa Tiên Cổ","tomTat":"Tin Thạch Hạo dùng trận pháp tại ba ngàn đường đá gây tổn thất cho nhiều cánh quân và làm Quân Đạo, Hắc Ám Thần tử chịu thiệt hại lan khắp các tiểu thiên thế giới, khiến hắn được nhìn nhận là người đủ sức sánh với các Vương cổ đại. Quái thai cổ đại của Thiên quốc nhờ thần giác nhạy bén đã không bước vào cạm bẫy và hoàn toàn không bị thương. Tại di tích bộ lạc Hàn giới, Thạch Hạo dùng Tiên kiếm Đại La quan sát cảnh cường giả mạnh nhất của bộ lạc lấy băng tuyết nhập đạo, diễn hóa Thái Âm và tiến sát cảnh giới thành Tiên. Nguyền rủa Tiên cổ thừa lúc người này chống thiên kiếp để xâm nhập nguyên thần, khiến ông nổ tung dù các trưởng lão đã vận chuyển tế đàn cứu viện. Một tia sức mạnh Thái Âm rơi xuống đóng băng toàn bộ Hàn giới, còn những người trong bộ lạc bình thản đón nhận cái chết như sự giải thoát khỏi nguyền rủa. Thạch Hạo hiểu rằng nguyền rủa từ kỷ nguyên trước đã ăn sâu vào huyết mạch dân bản địa, hạn chế phạm vi sinh tồn và gây điên loạn hoặc tử vong khi họ đạt cảnh giới cao. Sau khi cùng Thái Âm Ngọc Thỏ mai táng bộ lạc, hắn để nàng và Đả Thần Thạch đi tìm cơ duyên trong núi tuyết. Thạch Hạo lấy tiên chủng được thiên địa mẫu khí bao quanh khỏi mi tâm, bắt đầu chuẩn bị cho bước tu ra tia tiên khí tiếp theo."},{"chuong":905,"tieuDe":"Bị Bắt","tomTat":"Thạch Hạo tiếp tục con đường tu thành tiên khí bằng cách lĩnh hội tiên chủng, thiên địa mẫu khí và chuẩn bị lấy chư thiên vạn đạo làm lửa tôi luyện chân ngã. Trong tiểu thế giới U Nguyệt, Thanh Y và Nguyệt Thiền nhiều lần giao chiến vì quyền chủ đạo khi dung hợp; họ từng hòa làm một khiến Thanh Nguyệt diễm phát ra tiên khí, nhưng lại tách ra vì cùng muốn xóa dấu ấn của đối phương. Tại Hàn giới, Thạch Hạo dẫn động đạo hỏa thiêu thân suốt ba ngày, khiến núi tuyết tan chảy rồi tái hiện dưới ảnh hưởng của khí tức Tiên đạo. Hắn vượt qua cửa ải nhưng toàn thân cháy đen, gần như người chết đạo vong và phải tĩnh dưỡng trước khi tiếp tục hướng tới tia tiên khí thứ hai. Thanh Y mang thương thế đến núi tuyết, tỏ ý muốn ở lại chữa trị và bảo vệ hắn, còn Thái Âm Ngọc Thỏ cùng Đả Thần Thạch đi tìm tiên trân. Lợi dụng lúc Thạch Hạo suy yếu và mất cảnh giác, Thanh Y phong ấn cả thân thể lẫn nguyên thần của hắn rồi mang hắn vượt qua hư không rời đi."},{"chuong":906,"tieuDe":"Tù Nhân Của Tiên Tử","tomTat":"Nguyệt Thiền đưa Thạch Hạo tới một động phủ cổ trong Hàn giới và hoàn tất ba mươi sáu lớp phong ấn nhằm trấn áp cả thân thể lẫn nguyên thần của hắn. Khi Thạch Hạo nghi ngờ dao động linh hồn của nàng giống hệt Thanh Y, nàng hé lộ một tinh thể xanh hình đỉnh nhỏ có thể che phủ nguyên thần và mô phỏng sóng linh hồn. Nguyệt Thiền tiếp tục hành hạ hắn để trả thù chuyện cũ, khiến thương thế do lửa đại đạo gây ra càng nghiêm trọng, nhưng hắn vẫn không ngừng châm chọc nàng. Nàng sau đó thi triển tán thủ trong bảo thuật Tiên Hoàng, cưỡng ép dẫn tiên chủng chứa mẫu khí ra khỏi mi tâm Thạch Hạo để dò xét tia tiên khí mà hắn chưa chịu bộc lộ. Không thấy đòn phản kích như dự liệu, nàng đưa Tỏa hồn tháp vào sau mi tâm hắn và thu nguyên thần đã bị trói vào trong. Nguyệt Thiền không cưỡng ép lấy hẳn tiên chủng vì việc đó có thể hủy diệt mi tâm cùng nguyên thần Thạch Hạo, đồng thời làm bảo thuật Côn Bằng và bí thuật Lôi Đế thất truyền. Dù rơi vào tình thế bị khống chế, Thạch Hạo vẫn tỏ ra chưa khuất phục và tiếp tục dùng chuyện bái thiên địa để khiêu khích nàng."},{"chuong":907,"tieuDe":"Song Tiên","tomTat":"Nguyệt Thiền dùng Phược Long tác và Tỏa Hồn tháp khống chế thân thể cùng nguyên thần của Thạch Hạo, rồi dựng hiện trường giả để dụ Thanh Y xuất hiện. Thanh Y nhận ra một phần âm mưu nhưng vẫn một mình tiến vào dãy núi cứu Thạch Hạo, trong khi Đả Thần Thạch và Thỏ nhỏ chuẩn bị tiếp ứng từ xa. Nguyệt Thiền dùng Nguyên Thần Ảnh Tượng thuật đánh lừa Thanh Y, khiến nàng bị chân thân Nguyệt Thiền tập kích trọng thương. Thạch Hạo âm thầm điều khiển tàn lửa vạn đạo rồi dùng tiên chủng mang mẫu khí đánh Nguyệt Thiền trọng thương, nhưng bản thân cũng bị phản phệ đến mức mi tâm rạn nứt và cạn kiệt sức lực. Cuối chương, Thanh Y và Nguyệt Thiền hợp thành một thân thể, dùng nhiều bảo vật nguyên thần giao chiến trong thức hải, còn kết quả tranh quyền kiểm soát vẫn chưa được phân định."},{"chuong":908,"tieuDe":"Thanh Nguyệt Tiên","tomTat":"Thạch Hạo bị phong ấn trong khi Thanh Y và Nguyệt Thiền tranh đấu nguyên thần để giành quyền chủ đạo. Hắn liên tục chọc giận Nguyệt Thiền, giúp Thanh Y tìm cơ hội phản kích và đồng thời cố gắng phá giải phong ấn. Một cô gái mơ hồ sau cánh cửa vàng trong thức hải thức tỉnh, phân hồn lực hỗ trợ cả hai, còn Thanh Nguyệt diễm cộng hưởng với nguồn lực ấy và dấu ấn tiên chủng. Thanh Y cùng Nguyệt Thiền nhờ đó bắt đầu lột xác và ngưng tụ một tia tiên khí. Khi Nguyệt Thiền tiếp tục tìm cách xóa bỏ Thanh Y, Thanh Y kéo Thạch Hạo vào cuộc giằng co, còn đốm lửa thần bí trong cơ thể hắn đẩy lui ánh trăng xanh. Chương kết thúc khi Thạch Hạo và Nguyệt Thiền cùng sững sờ trước một biến cố chưa được giải thích."},{"chuong":909,"tieuDe":"Cô Gái Lực Sĩ Suy Sụp","tomTat":"Thanh Y tạm thời nắm quyền điều khiển thân thể chung và tiếp xúc gần với Thạch Hạo, khiến Nguyệt Thiền nổi giận, cố giành lại quyền chủ đạo và xóa dấu ấn của thứ thân. Thạch Hạo bị giam cầm giữa cuộc quyết đấu nhưng vẫn liên tục trêu chọc Nguyệt Thiền, sau đó cắn cổ và má nàng, khiến nàng mất bình tĩnh rồi đánh mất ưu thế. Khi Thanh Y sắp bị xóa bỏ, nàng chủ động dùng phương án ngọc đá cùng vỡ bằng cách giành quyền điều khiển thân thể và quấn lấy Thạch Hạo, buộc Nguyệt Thiền phải nhượng bộ. Nguyệt Thiền định giết cả hai nhưng bị ngọn lửa đi cùng Tam Thế Đồng quan uy hiếp. Cuối cùng thân thể chung phát sáng rồi phân thành Thanh Y và Nguyệt Thiền, Thanh Y ở lại trong động phủ còn Nguyệt Thiền suy sụp bỏ chạy."},{"chuong":910,"tieuDe":"Thỏ Nhỏ Đầy Hồn Nhiên","tomTat":"Thỏ nhỏ cùng Đả Thần Thạch lần theo dấu vết chiến đấu tới một dãy núi và gặp Nguyệt Thiền đang bỏ chạy. Hai bên giao chiến, khiến Nguyệt Thiền bị thương nặng nhưng vẫn phá băng và dùng Phá giới phù rời khỏi Hàn giới. Trong động phủ, Thạch Hạo lợi dụng sự liên hệ giữa Nguyệt Thiền và Thanh Y để đánh lừa Thanh Y giải một phần phong ấn trên người mình. Đả Thần Thạch che giấu sự việc với Thỏ nhỏ, khiến nàng hiểu lầm rằng Thạch Hạo và Thanh Y đang quyết đấu. Sau khi động phủ cùng ngọn núi sụp đổ, Thanh Y xuất hiện với một tia tiên khí mờ nhạt rồi tức giận rời đi. Thạch Hạo bước ra với thương thế chưa lành, quyết định dưỡng thương trước khi ra ngoài giết địch, trong lúc Quân Đạo cùng Minh thổ, Thiên quốc và Thần miếu chuẩn bị truy sát Hoang."},{"chuong":911,"tieuDe":"Khắp Nơi Toàn Là Địch","tomTat":"Nguyệt Thiền và Thanh Y tách khỏi Thạch Hạo, mỗi người ở một giới khác nhau và tìm cách bình tâm sau những chuyện đã xảy ra. Tại Hàn giới, Thạch Hạo dùng một tia tiên khí phá bỏ phong ấn còn lại của Tỏa Hồn tháp rồi thu lấy pháp bảo này, sau đó dùng thánh dược tĩnh dưỡng để chữa thương. Trong thời gian hắn bế quan, Minh Thổ, Thiên quốc và Thần miếu đồng loạt truy sát Hoang, khiến những người từng liên hệ với hắn cũng bị cuốn vào nguy hiểm. Lạc Đạo, Lam Nhất Trần và Lộ Dịch phải dựa vào bảo thuật biến hóa của tộc Chu Yếm để lẩn trốn, còn Tào Vũ Sinh bị Quân Đạo phục kích tại Trận giới. Sau khi hồi phục hoàn toàn, Thạch Hạo đi qua nhiều giới để tìm đồng bạn và gặp lại nhóm Lạc Đạo tại Côn giới. Biết Tuyết Lâm bị truy đuổi còn Tần Hạo bị dùng làm mồi nhử, hắn từ bỏ ý định tiếp tục né tránh và quyết định công khai đối đầu, chuẩn bị đại khai sát giới."},{"chuong":912,"tieuDe":"Kiếm Quang Chiếu Khắp Mười Giới","tomTat":"Lộ Dịch nhận ra Hắc Ám Thần tử, Thiên quốc và Quân Đạo đang cố ý nhắm vào những người xung quanh Thạch Hạo để dụ hắn bước vào sát cục. Thạch Hạo không chờ đối phương ra tay mà cầm Tiên kiếm Đại La và kiếm thai tiên kim tấn công các cứ điểm trên năm mươi chín tiểu thiên thế giới, khiến nhiều thế lực và bộ tộc phụ thuộc tổn thất nặng nề. Cổ Mông đại diện Thần miếu hiệu triệu thiên hạ diệt Hoang, còn Quân Đạo lên tiếng kể tội Thạch Hạo vì cái chết của Đọa Thần tử, nhưng đều bị Thạch Hạo sắc bén phản bác. Tin tức Tuyết Lâm bị vây tại Kim Linh giới truyền tới, trong khi sự hiện diện của Tần Hạo vẫn chưa được xác nhận. Thạch Hạo mang theo Đả Thần Thạch tiến vào Kim Linh giới, dùng cánh Côn Bằng và Võ đạo Thiên nhãn tìm thấy Tuyết Lâm đang bị Cổ Mông truy sát, rồi lập tức lao tới cứu nàng."},{"chuong":913,"tieuDe":"Tự Tin Không Gì Sánh Được","tomTat":"Thạch Hạo vận chuyển cánh Côn Bằng, bao phủ đôi cánh bằng lôi đình đen trắng rồi đánh lui Cổ Mông để cứu Tuyết Lâm đang trọng thương. Cổ Mông đề nghị đổi Tuyết Lâm lấy việc Thạch Hạo giết kim văn Bạch hổ, nhưng Thạch Hạo bác bỏ và vạch trần ý định kéo dài thời gian của hắn. Hắc Ám Thần tử cùng vương giả cổ đại của Thiên quốc lần lượt xuất hiện, phối hợp tạo thế mai phục; Thạch Hạo dùng linh thân và chân thân để hóa giải đòn sát phạt. Cổ Mông nhận ra Thạch Hạo đã tu ra một tia tiên khí và Quân Đạo đã lừa mình, nhưng vẫn bị linh thân Thạch Hạo truy kích chém chết, nguyên thần cũng bị tiêu diệt. Sau đó linh thân hợp nhất với chân thân, Thạch Hạo tiếp tục giao chiến với Hắc Ám Thần tử rồi truyền âm khiêu chiến mọi địch thủ xung quanh."},{"chuong":914,"tieuDe":"Hắc Ám Thần Tử","tomTat":"Thạch Hạo mở đầu bằng một kiếm chém chết truyền nhân mạnh nhất của Thần miếu rồi tiếp tục quyết đấu dữ dội với Hắc Ám Thần tử tại Kim Linh giới. Khí trắng quanh cơ thể hai người được nhận ra là tiên khí, khiến những người quan sát chấn động và xác nhận họ đều đã bước lên con đường tu thành tiên khí. Một sát thủ Thiên quốc nhân cơ hội đánh lén Thạch Hạo bằng pháp kiếm cấp Chân Thần, nhưng tia tiên khí hộ thể nghiền nát binh khí rồi khiến sát thủ vỡ thành sương máu mà Thạch Hạo không cần quay đầu. Trong những lượt giao phong kế tiếp, Thạch Hạo dùng Chân long trảo, Súc địa thành thốn cùng thế đá kết hợp Chân Long và Kim Xà, còn thân thể Hắc Ám Thần tử tự động giải phóng phù văn và bảo thuật để phản kích. Hắc Ám Thần tử tiết lộ thân thể hiện tại là phần tàn khuyết còn lại từ kiếp trước sau một giấc ngủ dài, đồng thời tuyên bố không ai trong Tiên cổ có thể giết mình. Thạch Hạo mở thiên nhãn và nhận ra tia tiên khí của đối phương không phải tự tu thành mà do thân thể tiền kiếp nuôi dưỡng. Hắc Ám Thần tử lập tức hóa cánh tay phải thành thần kiếm màu đen chém xuống, còn Thạch Hạo giương đôi cánh Côn Bằng lao tới tiếp tục trận chiến."},{"chuong":915,"tieuDe":"Kiếm Chém Thần Tử","tomTat":"Thạch Hạo thăm dò thân thể dị thường của Hắc Ám Thần tử và phát hiện các vùng phát sáng có thể là nơi phóng thích bảo thuật. Hắn diễn hóa mười vạn kiếm vũ Côn Bằng thành kiếm lô để phong tỏa đối thủ, nhưng Hắc Ám Thần tử phá giải phán đoán ấy và phát động Đọa Hồn thuật công kích nguyên thần. Thạch Hạo dùng động thiên duy nhất kết hợp Lôi điện, Côn Bằng và ánh sáng Thượng thương để tiêu diệt đòn công kích. Sau đó, hắn xác định những vị trí có thể phát ra bảo thuật mới là các vùng đã tổn hại theo năm tháng, rồi dùng kiếm thể Luân hồi–Thượng thương và Súc địa thành thốn liên tục tấn công. Thạch Hạo lấy Tiên kiếm Đại La, chém rời cánh tay phải, chém ngang hông và phân giải thân thể Hắc Ám Thần tử. Khi tiếng tụng Cửu thiên thập địa kinh vang lên cùng bóng người của Cổ Thánh tử của Thần miếu, Thạch Hạo hợp nhất song kiếm và chém đầu Hắc Ám Thần tử."},{"chuong":916,"tieuDe":"Nơi Tiên Kiếm Hướng Về","tomTat":"Thạch Hạo dùng Tiên kiếm Đại la chém đứt đầu Hắc Ám Thần tử, phá tan huyết hà bằng Bảo thuật Lôi Đế rồi tiếp tục nghiền nát thân thể đối phương. Cổ Thánh tử từ xa tụng Cửu Thiên Thập Địa kinh, diễn hóa một trăm lẻ tám núi phù văn và bàn tay khổng lồ để cản trở, nhưng Thạch Hạo dùng kiếm khí đánh tan thế công. Nhóm cường giả Minh thổ lao vào cứu viện cũng bị hắn quét kiếm tiêu diệt. Khi đầu lâu Hắc Ám Thần tử bị bổ vỡ, một chiếc đỉnh tàn phá bằng tiên kim hắc ám chứa nguyên thần của hắn lộ ra. Quái thai cổ đại của Thiên quốc nhân lúc Thạch Hạo phân tâm đánh xuyên thân thể hắn từ phía sau, song bị Võ đạo Thiên nhãn phát hiện và khóa đường lui. Trong lúc tiếp tục giao chiến, Thạch Hạo phóng tiên khí mang tàn lửa thiêu các mảnh máu thịt của Hắc Ám Thần tử đang định bao phủ mình. Cuối cùng, nắp đỉnh rơi xuống khiến nguyên thần Hắc Ám Thần tử văng ra và pháp khí mất khống chế; Thạch Hạo lập tức dùng tiên kiếm tách chiếc đỉnh khỏi đối phương rồi cướp lấy."},{"chuong":917,"tieuDe":"Chém Giết Quái Thai Cổ Đại","tomTat":"Hắc Ám Thần tử cố triệu hồi chiếc đỉnh nhỏ màu đen nhưng không được đáp lại, để Thạch Hạo tạm thời nắm giữ và phát hiện nó được luyện từ tiên kim hắc ám. Hắc Ám Thần tử triển khai tiểu thế giới mộ cổ cùng Bí thuật Tam Táng, song Thạch Hạo dùng Chí Tôn thuật phá tan vì phù văn của đối phương chưa hoàn chỉnh. Quân Đạo hoàn thành đại trận phong tỏa, còn Đả Thần Thạch xuất hiện trợ chiến và làm trận thế suy yếu. Hắc Ám Thần tử, Quân Đạo, Cổ Thánh tử và quái thai cổ đại của Thiên quốc đồng loạt vây công, buộc Thạch Hạo phải vừa chịu thương vừa tìm cách phá vòng vây. Thạch Hạo đánh Quân Đạo mất một cánh tay, liên tục chém vào các điểm yếu trên thân thể Hắc Ám Thần tử rồi dùng kiếm xuyên qua mi tâm khiến nguyên thần đối phương vỡ nát, dù thân thể cổ đại vẫn còn phản ứng theo bản năng. Khi trận pháp và hư không quanh chiến trường sụp đổ, Tiên dược viên cổ xưa hiện ra trong không gian loạn lưu với vô số dược thảo thần thánh, Trường Sinh dược, một con rùa trắng cùng cô gái áo trắng. Quái thai cổ đại của Thiên quốc, Cổ Thánh tử, Thạch Hạo và cường giả các tộc lập tức xông vào dược viên tranh đoạt cơ duyên."},{"chuong":918,"tieuDe":"Tiên Dược Viên","tomTat":"Trong dược viên cổ giữa vết rách hư không, một tiên tử áo trắng cưỡi Bạch Quy Đà Tiên xuất hiện, tỏa tiên vụ và phát ra tiếng ca khiến nhiều tu sĩ mất sát ý. Thạch Hạo nhận ra tiên tử chỉ là hình thái do Trường Sinh dược hiển hóa, không phải Chân Tiên chân chính. Cổ Thánh tử và vương giả cổ đại của Thiên quốc nhanh chóng tiến vào dược viên, kéo theo những người khác tranh nhau xông vào vì tin rằng Trường Sinh dược có thể đem lại trường sinh. Hư không loạn lưu sau đó hình thành những lưỡi chém vô hình, giết chết nhiều tu sĩ; Liệp Sát giả của Thiên quốc cũng bị Thạch Hạo dùng Tiên kiếm Đại La giam cầm hư không rồi chém chết. Thạch Hạo cảnh báo về Hư không đại liệt trảm và cùng Đả Thần Thạch tìm đường vượt qua phong tỏa thời không để đặt chân lên hòn đảo dược viên. Trên đảo, hai người phát hiện nhiều thánh dược, một cổ thụ Thiên Thần biết bỏ chạy và một tổ cổ có bóng phượng hoàng cùng khí tức Hoàng huyết, khiến Đả Thần Thạch suy đoán bên trong có thể là Hoàng Huyết thạch hoặc trứng Phượng hoàng."},{"chuong":919,"tieuDe":"Phượng Hoàng Sào","tomTat":"Thạch Hạo và Đả Thần Thạch phát hiện một Phượng Hoàng sào được bện từ Hoàng Vũ mộc trong Tiên dược viên cổ. Đả Thần Thạch suy diễn tàn trận Tiên đạo bao phủ khu vực và dùng hàng trăm trận kỳ cùng Xúc Trận thuật để tìm lối đi an toàn. Tuyết Lâm gia nhập đội ngũ vì hoàng huyết trong cơ thể cộng hưởng với cổ sào, rồi huyết dịch của nàng kích hoạt Phượng Hoàng sào và đưa cả ba người vào bên trong. Tuyết Lâm được đạo đài năm màu dẫn vào trạng thái ngộ đạo, còn Đả Thần Thạch nuốt bốn khối Hoàng Huyết thạch để thử tu ra tiên khí. Thạch Hạo thu được một cọng lông Phượng hoàng năm màu có thể phát ra Hư không trảm và dự định dùng nó luyện quạt Ngũ Cầm. Cuối chương, một cây thần dược màu hắc kim truyền lời rằng Quy Tiên đại nhân muốn gặp Thạch Hạo."},{"chuong":920,"tieuDe":"Mời","tomTat":"Hắc Hâm thần dược xuất hiện thay mặt một sinh linh ở suối tiên mời Thạch Hạo tới gặp mặt, nhưng hắn cảnh giác vì dược đảo có trận pháp Tiên đạo đủ sức giết Thiên Thần. Để bảo đảm an toàn, Hắc Hâm đề nghị tự làm con tin rồi định gọi Thiên Thần thụ tới cùng bảo chứng, khiến cây thần dược này lập tức bỏ chạy vì sợ bị Thạch Hạo bắt giữ. Sau khi cân nhắc, Thạch Hạo chấp nhận lời mời và cùng Đả Thần Thạch theo Hắc Hâm tiến sâu vào đảo, còn Tuyết Lâm ở lại Hoàng sào bảo vệ đường lui. Nhóm vượt qua cổng ánh sáng, đường hầm hư không và nhiều khu vực được trận pháp cổ bảo vệ. Tại khu cổ địa, họ chứng kiến kiếm khí đi kèm tiên khí hủy diệt các tiểu thiên thế giới và được biết uy lực nguyên bản của nó từng có thể chém đứt đại thế giới. Khi tới di tích phủ sương mù hỗn độn, Thạch Hạo hỏi mục đích triệu kiến nhưng sinh linh bí ẩn chỉ nói về vạn vật héo úa, thế gian tịch diệt, màn đêm vĩnh hằng và một kỷ nguyên mới mở ra sau luân hồi."},{"chuong":921,"tieuDe":"Bạch Quy Đà Tiên","tomTat":"Trong màn sương trên hòn đảo bị phong ấn, Thạch Hạo nghe một cây Trường Sinh dược cảnh báo rằng thế giới hiện tại rồi sẽ đi vào kết cục diệt vong như kỷ nguyên trước, khiến hắn càng nhận thức rõ sự khốc liệt của đại kiếp tương lai. Khi sương mù tan đi, Vạn Vật thổ rộng lớn lộ ra, Bạch Quy Đà Tiên cùng mỹ nhân áo trắng xuất hiện và đề nghị kết thiện duyên với hắn để đổi lấy cơ hội phá giải phong ấn hòn đảo. Bạch Quy tặng Đả Thần Thạch nửa khối Thiên Khuyết thạch, đồng thời trao cho Thạch Hạo một giọt dược dịch Trường Sinh và một quả Quy đan. Sau đó, nó dẫn hắn đến Bất Lão tuyền, nơi có một sợi kim liên tiên kim bị phong giữ, và nhờ hắn chặt đứt nó. Kiếm thai đen vừa tiếp xúc với kim liên đã tự động hấp thu tiên kim quang minh, khiến tiên vụ trắng cùng sinh linh hình người trên thân kiếm trở nên rõ ràng hơn, nhưng lai lịch kỳ dị của thanh kiếm vẫn không ai nhớ ra. Nhận thấy Thạch Hạo đang dùng vạn đạo thiêu luyện bản thân để tu thành tia tiên khí thứ hai, Bạch Quy cảnh báo con đường này từng khiến một tiểu Tiên vương bị thiêu rụi, rồi đề nghị đưa hắn vào Nhân Tiên điện để tìm cơ duyên cứu chữa."},{"chuong":922,"tieuDe":"Nhân Tiên Điện","tomTat":"Bạch Quy tiết lộ Nhân Tiên điện từng là nơi tu đạo và luyện Trường Sinh dược, đồng thời cảnh báo về sự thoái hóa của thiên địa, đại loạn sắp tới và một địa phương trường sinh thật sự nằm ngoài thượng giới. Đúng lúc đó, kiếm thai hấp thu toàn bộ tiên kim Quang Minh trong Bất Lão tuyền, khiến bảo liên đứt rời và giải phóng Bạch Quy khỏi sự trấn áp. Thạch Hạo đưa Lạc Đạo, Lam Nhất Trần, Thái Âm Ngọc Thỏ cùng Lộ Dịch vào dược viên cổ, rồi được Hắc Hâm thần dược dẫn qua các đường hầm hư không đến khu cổ địa trước Nhân Tiên điện. Bỏ Đả Thần Thạch ở ngoài, Thạch Hạo một mình bước vào thạch điện và chứng kiến những cảnh tượng kinh người về Côn Bằng, Chân long, bàn tay đen cùng sự hình thành thiên địa. Những bức tranh đá lần lượt phát động thử thách, buộc hắn đánh bại một sinh linh mang theo tia tiên khí và chống đỡ mười ngôi sao khổng lồ, dù toàn thân bị thương nặng. Vượt qua cửa ải, Thạch Hạo nhận ra hệ thống tu hành Tiên cổ hoàn toàn khác với đương đại, đồng thời càng thêm kinh sợ trước sức mạnh của những kẻ từng hủy diệt cả kỷ nguyên Tiên cổ."},{"chuong":923,"tieuDe":"Cơ Duyên Thập Tử","tomTat":"Trong thạch điện của Nhân Tiên điện, Thạch Hạo dùng nguyên thần đối đầu thử thách ở cửa thứ ba và nhờ Lôi đạo cùng phù văn Thượng thương đánh tan đối thủ. Bạch Quy và Đả Thần Thạch ở bên ngoài theo dõi tình trạng của hắn qua hồn đăng, đồng thời tranh luận về mức độ nguy hiểm của thí luyện. Tại cửa thứ tư, tiên chủng Vạn Vật mẫu khí giúp Thạch Hạo dễ dàng áp đảo thử thách đạo chủng. Sau đó hắn chịu thương tích nặng nhưng vẫn vượt đủ mười cửa, đạt thành tích khiến Bạch Quy liên tưởng tới Tiểu Tiên vương. Trong mật thất cuối cùng, Thạch Hạo nhận ra mình có cơ hội thức tỉnh lại mười lần khi ngộ đạo hoặc tử vong. Hắn lấy tiên chủng ra, kết nối Vạn Vật mẫu khí với quy tắc chư thiên và bắt đầu dùng thiên địa làm lò, vạn đạo làm lửa để đốt cháy chân ngã."},{"chuong":924,"tieuDe":"Vô Sinh","tomTat":"Trong mật thất rộng mười trượng thuộc thạch điện, Thạch Hạo cầm Tiên chủng, lấy thiên địa làm lò và vạn đạo làm lửa để rèn gân cốt cùng hồn phách. Vạn đạo nhiều lần xuyên thủng thân thể khiến hắn phải thu Vạn Vật Mẫu khí, dùng thánh dược chữa thương rồi tiếp tục suy diễn con đường tu luyện. Sau một lần vạn hỏa mất kiểm soát, thể xác và nguyên thần của hắn nổ tung, nhưng linh thức, huyết dịch, xương thịt và nguyên thần đã tái hợp giúp hắn phục sinh. Hắn nhìn thấy trên vách đá dấu vết của Tiểu Tiên vương thời Tiên cổ, người từng đi cùng con đường vạn đạo thiêu thân để tìm luồng tiên khí thứ hai nhưng cuối cùng thất bại. Thạch Hạo tiếp tục chết và phục sinh tổng cộng chín lần mà vẫn chưa thành công, đồng thời hiểu thêm về động lực chiến đấu của Tiểu Tiên vương sau cái chết của phụ thân người này. Cuối chương, hắn bắt đầu lần bế quan thứ mười với cơ hội phục sinh cuối cùng."},{"chuong":925,"tieuDe":"Thất Bại","tomTat":"Thạch Hạo tiến hành lần bế quan cuối để thử tu ra luồng tiên khí thứ hai, cầm tiên chủng và chịu Vạn Đạo phù văn diễn hóa thành lò thiên địa rèn luyện. Vạn vật cùng các lực quy tắc liên tục công kích khiến lò thiên địa nứt vỡ, thân thể và nguyên thần của hắn bị hủy diệt; hắn chết lần thứ mười rồi phục sinh nhưng vẫn thất bại. Những hình ảnh về Tiểu Tiên vương cho thấy người này từng chết đủ mười lần trên con đường tương tự và cuối cùng tử vong sau khi ngộ đạo thất bại, khiến Thạch Hạo suy xét nguy cơ đường cụt. Hắn không từ bỏ mà quyết định bế quan nghiên cứu kỹ con đường, đồng thời vào nhà đá luyện dược rút lấy tinh hoa dược tính phong ấn vào bình ngọc. Rời khỏi di tích, Thạch Hạo gặp Bạch Quy, nghe thêm lời đồn về con đường thập tử vô sinh rồi chuẩn bị hái thánh dược để tiếp tục bế quan."},{"chuong":926,"tieuDe":"Trở Về","tomTat":"Bạch Quy cảnh báo Thạch Hạo rằng con đường dùng Vạn đạo đốt thân từng khiến tiểu Tiên vương thất bại, nhưng Thạch Hạo vẫn quyết định tiếp tục vì không còn lựa chọn nào khác. Thiếu nữ áo trắng kể về những con đường Tiên đạo huyền diệu của Tiên cổ, gồm việc dùng Thế Giới thụ làm tiên chủng và dung hợp hạt giống mô hình vũ trụ với thân thể. Hòn đảo cổ sắp tiến vào hư không loạn lưu, nên Thạch Hạo từ bỏ kế hoạch bế quan tại đền đá, còn Bạch Quy ở lại trong tàn trận Tiên đạo để chờ cơ hội xuyên qua giới bích. Trước khi rời đi, Thạch Hạo lấy một lá Hắc Hâm thần dược và niêm phong tinh hoa vào bình ngọc, Hoàng điệp hấp thu phấn hoa Thiên Thần thụ, còn Thái Âm Ngọc Thỏ thu hái rất nhiều dược liệu. Chân Hoàng sào trên núi cụt thu nhỏ rồi bay vào tay Tuyết Lâm, trong khi Cổ Thánh tử của Thần miếu rời khỏi đảo. Sau đó Quân Đạo loan tin Thạch Hạo đã lấy Trường Sinh dược, người của Thần miếu còn nói hắn chiếm cả Chân Hoàng sào, khiến khu vực bạo loạn và biến Hoang thành mục tiêu chung."},{"chuong":927,"tieuDe":"Sóng Gió Lại Nổi","tomTat":"Thạch Hạo rời dược viên cổ trong thời không loạn lưu và đưa nhóm Tuyết Lâm thoát khỏi khu vực nguy hiểm. Trước sự kích động của đám đông, hắn chém chết nhiều kẻ khiêu khích rồi tuyên chiến với Thiên quốc, Thần miếu và Quân Thiên cảnh. Hắn truy tìm và huyết sát người của ba thế lực tại nhiều thành trì trong ba ngày, khiến toàn Tiên cổ chấn động và các quái thai cổ đại xuất quan điều tra. Sau đó Thạch Hạo chia tay đồng bạn, đề nghị họ tới Nhân Mã tộc, đồng thời chôn chiếc đỉnh đen trong dung nham và bố trí trận pháp che giấu. Tại một tiểu thế giới không rõ tên, hắn dựng trận thế nghi binh rồi bắt đầu bế quan, cầm tiên chủng và dùng đạo hỏa thiêu luyện thân thể cùng nguyên thần. Trong lúc đó, Quái thai cổ đại của Thiên quốc tới gặp Đế Côn và báo tin truyền nhân Tiên điện Đế Trùng đã chết. Ba thế lực tiếp tục treo thưởng và điều động nhân mã khắp các tiểu thiên thế giới để truy tìm Thạch Hạo."},{"chuong":928,"tieuDe":"Vượt Cửa Ải Lần Cuối Cùng","tomTat":"Đả Thần Thạch bố trí nhiều sát trận liên kết thành tuyệt địa quanh động phủ, bảo vệ Thạch Hạo trong lúc hắn bế tử quan. Thạch Hạo dùng vạn Đạo nung luyện thân thể và nguyên thần để tìm cách ngưng tụ luồng tiên khí thứ hai, nhiều lần tỉnh táo dừng lại chữa thương khi nhận ra sinh cơ sắp cạn. Sau một lần rơi vào trạng thái gần như vĩnh tịch, hắn cưỡng ép ý thức trở về, dùng thần dược và Bát Trân kỳ cứu mạng rồi tiếp tục tu luyện. Hắn còn thử gửi gắm nguyên thần vào tiên chủng nhưng không thể xuyên thủng vật này, từ đó nhận định cảnh giới hiện tại vẫn chưa đủ. Cuối cùng, luồng tiên khí thứ hai màu trắng nõn ngưng tụ thành hình, song nguyên thần hắn lại ly thể và bị phong trong một nhà giam hắc ám. Tại đó, hắn nhìn thấy nhiều nhà giam tương tự trôi trong dòng sông thời gian, bên trong giam giữ những sinh linh cổ xưa đáng sợ. Đúng lúc Thạch Hạo chưa thể trở về thể xác, Quân Đạo cùng các vương giả cổ đại của Thiên quốc tiến vào tiểu thế giới và từng bước áp sát nơi hắn bế quan."},{"chuong":929,"tieuDe":"Tuyệt Cảnh Tráng Hồn","tomTat":"Nguyên thần Thạch Hạo tỉnh lại trong một nhà giam hư vô lạnh lẽo và bị bóng tối liên tục ăn mòn. Hắn nhớ tới thất bại của Tiểu Tiên vương, rồi phát hiện khí tức Tiên đạo còn sót lại trong chân ngã có thể giúp chống ăn mòn và hấp thu hồn lực từ hư vô. Sau nhiều lần dưỡng hồn, phá ngục thất bại và chịu phản phệ, nguyên thần của hắn được tôi luyện mạnh mẽ đến mức khủng khiếp. Thạch Hạo cuối cùng đánh xuyên nhà giam, nhìn thấy dòng sông thời gian cùng những nhà giam khác nhưng vẫn chưa tìm được đường trở về. Trong khi đó, Quân Đạo, vương giả Thiên quốc, Cổ Thánh tử của Thần miếu và thuộc hạ nhờ đại sư trận pháp bản địa tiến vào lòng núi, phát hiện thân thể hắn không có sóng linh hồn và lập tức chuẩn bị ra tay."},{"chuong":930,"tieuDe":"Gọi Hồn","tomTat":"Thạch Hạo đang trọng thương trong lòng núi thì bị Vương giả cổ đại của Thiên quốc dùng sát kiếm đâm xuyên mi tâm, còn Quân Đạo dùng chiến mâu bạc xuyên thủng trái tim. Dù thân thể gần như tan rã, hai luồng tiên khí vẫn duy trì và tái tạo thân thể, khiến các cường giả muốn giữ lại thi thể có giá trị đặc biệt này. Cổ Thánh tử phát hiện nguyên thần Thạch Hạo không ở trong đầu lâu, trong khi nguyên thần của hắn đang bị giam tại một không gian hắc ám. Thạch Hạo phá vỡ nhà giam nhưng chưa tìm được đường trở về, cho đến khi nghe tiếng gọi hồn và nhìn thấy các ký hiệu do Cổ Thánh tử truyền tới. Nguyên thần trở về nhập thể khi chiến mâu vẫn ghim trong lồng ngực, Thạch Hạo tỉnh lại, nắm chặt thân mâu và lập tức xuất thủ về phía Quân Đạo."},{"chuong":931,"tieuDe":"Oai Phong Của Hai Luồng Tiên Khí","tomTat":"Quân Đạo phát hiện Thạch Hạo vẫn còn sống dù mi tâm và trái tim từng bị chiến mâu xuyên thủng. Thạch Hạo dùng thần âm làm Quân Đạo thổ huyết, ngăn phù văn trên chiến mâu rồi chặt gãy binh khí. Sau khi hai luồng tiên khí quấn quanh thân thể khiến hắn gần như vạn pháp bất xâm, Thạch Hạo phá Quân Thiên thuật, nghiền nát nắm đấm và kéo đứt cánh tay Quân Đạo. Quân Đạo bị xé nát thân thể, rồi bị chính đoạn mâu gãy xuyên mi tâm và diệt nguyên thần. Thạch Hạo tiếp tục chém chết đại sư trận pháp trước khi sát trận hoàn thành, làm Cổ Thánh tử bị phản chấn nguyên thần, rồi đánh gãy thần kiếm và đánh vỡ thân thể vương giả của Thiên quốc."},{"chuong":932,"tieuDe":"Rồng Dữ Rời Hang","tomTat":"Hai tia tiên khí của Thạch Hạo phá hủy thân thể đầu lĩnh sát thủ Thiên quốc, buộc hắn phải tự chặt bỏ hai chân để ngăn thương thế lan rộng. Ngay sau đó, các ẩn thương chí mạng của Thạch Hạo phát tác, nhưng hắn vẫn bị Cổ Thánh tử, đầu lĩnh sát thủ và những người đi theo vây công. Thạch Hạo kết hợp bảo thuật Thượng Thương với Luân Hồi quét chết năm, sáu mươi cường giả, đồng thời dùng tiên kiếm Đại La trấn áp dị tượng của Bạch Cốt phiên rồi phá hủy pháp khí này. Luân Hồi quyền sau lần lột xác đầu tiên đánh nát thân thể đầu lĩnh sát thủ; khi hắn định trốn qua không gian mặt kính, Thạch Hạo phá cửa thần và luyện cả máu thịt lẫn nguyên thần của hắn thành tro. Cuối cùng, Cổ Thánh tử triệu hoán chiến hồn nhập thể để quyết chiến, nhưng bị tiên kiếm Đại La phá tan phòng ngự và đâm vào mi tâm."},{"chuong":933,"tieuDe":"Người Mạnh Nhất Hiện Thân","tomTat":"Cổ Thánh tử mở cánh cửa chứa khí hỗn độn ở mi tâm để giam tiên kiếm Đại la, đồng thời triệu tập anh linh và tàn hồn cường giả đã chết nhập vào thân thể nhằm ép Thạch Hạo cận chiến. Thạch Hạo thi triển Luân Hồi, dùng xích thần trật tự mang sức mạnh thời gian kết hợp hai luồng tiên khí xuyên qua lớp phòng ngự bảo dịch, trực tiếp tấn công phủ tạng khiến Cổ Thánh tử lão hóa suy kiệt. Khi cánh cửa mi tâm mất ổn định, tiên kiếm Đại la thoát ra chém rơi đầu và cắt đứt nguyên thần Cổ Thánh tử, Thạch Hạo phong tỏa hư không tiêu diệt toàn bộ mảnh nguyên thần rồi thu tiên khí còn lại để luồng thứ hai luyện hóa. Ba vương giả gồm Cổ Thánh tử, Quân Đạo và vương giả Thiên quốc đều bị xác nhận đã chết. Một thanh niên bí ẩn áo xanh cầm sáo ngọc từ Hung sào xuất hiện, được nhận diện là kẻ từng ra vào Tiên cổ sáu hoặc bảy đời, chôn giết vô số thiên tài. Thập Quan vương hiện thân trong khí hỗn độn cùng cây non Tiên Đạo, ngăn âm phù từ sáo ngọc của thanh niên Hung sào, hai chí cường giả thăm dò rồi thu tay. Lục Quan Vương Ninh Xuyên đạp sách cổ mang Thiên đồ tới chiến trường, cùng nhiều quái thai cổ đại khác đồng loạt xuất hiện, cho thấy việc Thạch Hạo tu thành luồng tiên khí thứ hai đã kinh động hàng loạt nhân vật mạnh nhất Tiên cổ."},{"chuong":934,"tieuDe":"Tiếp Dẫn","tomTat":"Sau trận chiến với Cổ Thánh tử, Thạch Hạo mang thương tích nghiêm trọng, cầm Tiên kiếm Đại La lui về vị trí vững chãi trong khi Ninh Xuyên, Thập Quan vương, Trích Tiên và nhiều vương giả cổ đại cùng hội tụ. Hoàng Kim Đạo cung thuộc kỷ nguyên trước hiện ra từ hư không, báo hiệu võ đài Tiên Đạo và cuộc tranh bá cuối cùng của Tiên cổ sắp mở màn. Trích Tiên dùng sáo xương trắng, Thập Quan vương gọi ra cây nhỏ trong khí hỗn độn, còn các cường giả khác cũng thi triển thủ đoạn giao cảm với cổ cung. Một nguyên thần mang hình hài trẻ nhỏ bất ngờ xông vào Đạo cung, bị thiêu mất chín phần mười thân thể nhưng vẫn thành công tiến vào trong. Tấm bảng cổ hiện ra và được một di dân đọc thành hai chữ Tiếp dẫn, còn Thạch Hạo nhận thấy khí tức của nguyên thần tương hợp với nhà giam u tối nên nghi ngờ sinh linh ấy từng được gọi hồn trở về cùng mình. Võ đài Tiên Đạo thoáng xuất hiện bên cạnh cung điện rồi cả hai cùng biến mất, khiến các vương giả không thể truy tìm. Khi Thạch Hạo định rời chiến trường, Ninh Xuyên công khai sát ý và một Thiên Thần chưa rõ danh tính phóng thích vực tràng giam cầm bốn phương, buộc hắn phải dừng lại."},{"chuong":935,"tieuDe":"Thiên Thần Mã Nguyên","tomTat":"Mã Nguyên xuất hiện với uy thế Thiên Thần và lấy cớ mời Thạch Hạo về bộ tộc làm khách, trong khi Thạch Hạo đang trọng thương phải dùng dược vật cùng Bát Trân kỳ để kéo dài thời gian hồi phục. Nhờ Thiên Nhãn thông, Thạch Hạo nhìn ra sự tham lam và ý đồ đoạt xác của Mã Nguyên, buộc hai bên trở mặt. Tràng vực không tên phong tỏa chiến trường khiến Phá Giới phù mất tác dụng, nhưng Thần phù bảo vệ đã chặn đòn và bẻ gãy ngón tay Mã Nguyên. Nguyên thần lực của Thạch Hạo tăng mạnh nhờ quá trình tu hành trong nhà giam bóng tối, giúp hắn gắng gượng chống lại uy thế thần thức của Thiên Thần. Thạch Hạo dụ Mã Nguyên áp sát rồi dùng Tiên chủng kích phát thiên địa mẫu khí, đánh nát bàn tay đối phương. Sau đó hắn dùng lò luyện đan trút nước Thiên Hà cùng nguyền rủa vào vết thương, khiến Mã Nguyên đau đớn và gào thét."},{"chuong":936,"tieuDe":"Thiên Thần Xui Xẻo","tomTat":"Máu từ bàn tay bị thương của Mã Nguyên rơi xuống với uy lực xuyên thủng núi, khiến sinh linh xung quanh thương vong và mọi người phải lui tránh. Sau khi dùng pháp lực khôi phục bàn tay, Mã Nguyên nhận ra giá trị của tiên chủng cùng thân thể Thạch Hạo và tiếp tục phong tỏa hắn để chiếm đoạt. Việc vận dụng đại thần thông khiến nguyền rủa trong nước thiên hà chồng lên nguyền rủa Tiên cổ, làm Mã Nguyên xuất hiện thi ban, phun máu đen và bị mục ruỗng thân thể. Hắn phải chém bỏ cánh tay cùng một phần cơ thể, thiêu đốt tinh khí và hao tổn tuổi thọ để chống lại phản phệ. Thạch Hạo cố ý chế nhạo nhằm ép đối phương tiếp tục dùng pháp lực, rồi ném bùn vàng nhiễm nguyền rủa khiến một mảng thịt của Mã Nguyên hóa thành máu mủ. Mã Nguyên đánh bật bùn vàng và liều lĩnh tung ba chưởng, nhưng thần phù bảo vệ vẫn che chở Thạch Hạo. Khi nguyền rủa tiếp tục làm Thiên Thần suy yếu, vực tràng phong tỏa quanh Thạch Hạo cũng bắt đầu sụp đổ."},{"chuong":937,"tieuDe":"Thiên Thần Lệnh","tomTat":"Mã Nguyên giao chiến với Thạch Hạo trong trạng thái suy yếu nhưng phải chủ động rút lui sau khi Trường Cung Diễn bắn thần tiễn hỗ trợ. Trước khi rời đi, hắn ban Thiên Thần lệnh truy sát Hoang trên khắp các tiểu thiên thế giới, còn Thạch Hạo dùng Phá Giới phù thoát khỏi chiến trường. Tin Hoang tu thành hai luồng tiên khí, giết ba vương giả cổ đại và mang Cuống rốn thiên địa nhanh chóng chấn động Tiên cổ, khiến nhiều Thiên Thần muốn xóa thần thức rồi chiếm thân thể hắn. Mang Đạo thương chưa lành, Thạch Hạo lưu vong qua nhiều thế giới nhỏ, giết Đà Lam cùng hơn mười Cầu Long cấp Chân Thần để lấy huyết nhục duy trì thương thế. Thiên Thần của Hoàng kim cự tượng tộc, Cầu Long tộc, Long Tước tộc và một sư tử già màu trắng bạc sau đó hợp vây, buộc hắn quyết định phải đột phá trước khi báo thù. Nhờ lời cầu viện của Tuyết Lâm, Đả Thần Thạch và nhóm Thỏ nhỏ, Nhân Mã tộc, Bát Tí Hồn tộc cùng Cổ Ma tộc điều cường giả tới bảo vệ Hoang để đáp lại thiện duyên từ cành Liễu Thần. Cuối chương, một ông lão cường đại công khai che chở Thạch Hạo, dùng tiếng hét và uy thế khiến quần sơn sụp đổ, làm các đại Thiên Thần truy sát chấn kinh."},{"chuong":938,"tieuDe":"Nguy Cơ Sống Còn","tomTat":"Thiên Thần tuyệt đỉnh của Bát Tí Hồn tộc cùng cường giả Cổ Ma tộc và Nhân Mã tộc công khai bảo vệ Thạch Hạo, đồng thời tranh luận gay gắt với phe săn bắt về Cổ tổ Tế Linh. Sau khi voi vàng bị đánh bị thương, Cầu Long, Long Tước và nhiều Thiên Thần khác tham gia đối đầu, nhưng tất cả phải rút lui khi một hóa thân cấp Giáo chủ xuất hiện cảnh cáo. Đoàn cứu viện gồm Thái Âm Ngọc Thỏ, Đả Thần Thạch, Tuyết Lâm, Lộ Dịch và Lam Nhất Trần tới vùng núi thì Thạch Hạo đã chủ động rời đi. Trên đường tìm nơi che chở, hắn lần lượt bị một Thiên Thần Cổ Ma tộc và một Thiên Thần Nhân Mã tộc giả vờ tiếp cận rồi đánh lén, buộc phải dùng Tiên kiếm Đại La cùng Phá Giới phù chạy qua các tiểu thiên thế giới. Mũi tên mang pháp tắc Thiên Thần vẫn quẹt trúng khiến thương thế của hắn nặng thêm, trong khi bí bảo truy dấu và sự thông thuộc địa hình của các dị tộc làm Thất Thập Nhị Biến khó che giấu chân thân. Nhận ra thiện ý của đa số thành viên các đại tộc không thể bảo đảm an toàn trước lòng tham của từng Thiên Thần, Thạch Hạo quyết không nương nhờ bất kỳ bộ tộc nào nữa. Giữa lúc Phá Giới phù đã hao quá nửa và nguy cơ sống còn bủa vây, hắn quyết chữa lành thương thế, độ thiên kiếp đã biến mất trong kỷ nguyên hiện tại và đột phá để tự nắm giữ vận mệnh."},{"chuong":939,"tieuDe":"Giành Giật Từng Giây","tomTat":"Sau hai ngày chạy trốn khỏi Nhân Mã tộc, Thạch Hạo ẩn trong vùng núi hoang và dùng lão dược cùng thịt Ngạc Long cấp Chân Thần làm dược thực chữa Đạo thương, nhưng thân thể vẫn phải nhờ nguyên thần lực và hai luồng tiên khí duy trì. Một vượn cổ biến dị cảnh giới Thiên Thần đuổi tới, buộc hắn tiêu hao Phá Giới phù để tiến vào Táng giới. Khi định vào Táng thành và Hắc uyên, hắn phát hiện Hoàng kim cổ Tượng, Long Tước cùng Cầu Long đã bố trí mai phục, dùng nhiều bí bảo liên tục phá hao Thần phù bảo vệ. Nguyền rủa Táng giới bất ngờ phát tác, khiến cả ba Thiên Thần bị thối rữa, bong vảy và xuất hiện thi ban nên phải tháo chạy. Khói đen từ Hắc uyên tiếp tục trào lên, sát thương dân bản địa Tiên cổ và buộc Thạch Hạo rời khỏi khu vực vì đường vào đã bị trận pháp phong tỏa. Trong lúc các Thiên Thần trở về bộ lạc để đối phó chu kỳ nguyền rủa, Đế Côn lộ bí mật sở hữu thân thể Thiên Thần già cùng thân thể Thần Hỏa trẻ do nguyên thần đoạt xác quái thai cổ đại. Thạch Hạo tận dụng khoảng yên tĩnh hiếm hoi, tiếp tục vận chuyển cốt văn, tìm dược thảo chữa thương và chuẩn bị đột phá để tự vệ."},{"chuong":940,"tieuDe":"Đời Sau Của Nhân Tiên","tomTat":"Để nhanh chóng chữa thương, Thạch Hạo cướp sạch một số phòng đấu giá được các đại tộc nâng đỡ nhưng vẫn không tìm được Thần dược, nên phải trốn vào Ám giới. Đế Côn tìm tới, tự nhận là hậu nhân Nhân Tiên và đòi Thạch Hạo giao thể xác hoặc tự sát. Thạch Hạo dùng Đại La tiên kiếm cùng Luân Hồi quyền phá hủy thân thể phân hóa của đối phương, nhưng nguyên thần Đế Côn lập tức dùng Lạc Hồn chung tập kích thần hồn hắn. Nhờ Thần Hỏa, hai luồng tiên khí và Vạn Linh đồ thức tỉnh, Thạch Hạo ngăn được tiếng chuông, đánh trọng thương rồi bắt giữ nguyên thần Đế Côn. Chân thân Đế Côn đã đạt cảnh giới Thiên Thần xé hư không tới Ám giới truy sát, buộc Thạch Hạo chạy về phía Hỗn Độn Văn hồ. Thạch Hạo mặc giáp trụ rách nát, dùng Vạn Linh đồ hộ thân và mang nguyên thần bị bắt lặn sâu xuống hồ, trong khi Đế Côn phải cắt đứt liên hệ với nguyên thần phân hóa. Đàn muỗi ma hóa từ Thần Hỏa cảnh đến Thiên Thần cảnh tràn ra tấn công khiến chân thân Đế Côn phải rút lui, còn hai con muỗi tỏa khí hỗn độn đáng sợ hơn tất cả xuất hiện ở cuối chương."},{"chuong":941,"tieuDe":"Hỗn Độn Văn Hồ","tomTat":"Đế Côn bị hai con muỗi Hỗn Độn cổ xưa tập kích tại Hỗn Độn Văn hồ, mất phần lớn tinh huyết Thiên Thần và một tia nguyên thần. Sau khi quay lại canh giữ hồ để bắt Thạch Hạo, tia nguyên thần còn sót lại của hắn bị đàn muỗi hút sạch, khiến hắn tử vong. Thạch Hạo rơi xuống hồ nhưng sống sót, chịu sát khí và sự tấn công của vô số muỗi khổng lồ. Hắn dùng nước thiên hà từ lò luyện đan để công kích đàn muỗi, rồi nhờ Vạn Linh đồ khiến các muỗi cấp cao rút lui. Sau hơn nửa tháng dưỡng thương, Thạch Hạo lặn xuống đáy hồ sâu khoảng bốn mươi ngàn trượng và phát hiện cảnh tượng liên quan đến Thập hung, rồng cùng một người phụ nữ bí ẩn. Trong khi đó, ngoại giới cho rằng Hoang đã chết; Thanh Y im lặng, Tiểu Bạch đau buồn còn Đả Thần Thạch tuyên bố sẽ báo thù cho hắn."},{"chuong":942,"tieuDe":"Rèn Luyện","tomTat":"Dưới đáy Văn hồ hỗn độn, Thạch Hạo phát hiện một cô gái tóc xanh mặc giáp tiên kim Hắc Ám cùng một đoạn Chân Long cốt có hai con cổ văn hỗn độn bám trên đó. Khi đến gần cô gái, hắn bị sức mạnh bảo hộ đánh trọng thương, nhưng nhận ra khí tức sinh mệnh của nàng có thể giúp mình chữa trị. Sau nhiều tháng hấp thu khí tức ấy, Đạo thương của Thạch Hạo hoàn toàn khôi phục và luồng tiên khí thứ hai đạt đến viên mãn. Hắn quyết định tiếp tục rèn luyện thân thể để chuẩn bị chủ động dẫn thiên kiếp. Thạch Hạo ngồi trong hồ nước đen chịu đựng sát khí và sự ăn mòn, rồi dùng những con muỗi cấp Chân Thần làm đối tượng tôi luyện. Sau gần một tháng, thể phách của hắn trở nên cứng chắc hơn, khiến hắn quyết định xuất quan và rời khỏi hồ để độ kiếp."},{"chuong":943,"tieuDe":"Hoang Quay Về","tomTat":"Hơn nửa năm sau khi Thạch Hạo rơi xuống Hỗn độn Văn hồ, nhiều người trong Tiên cổ và bên ngoài đều cho rằng hắn đã chết. Tào Vũ Sinh xuất quan và thề báo thù, trong khi Thanh Y, Thỏ nhỏ, Trường Cung Diễn cùng cha mẹ Thạch Hạo đều thể hiện sự đau buồn hoặc quan tâm. Tiên cổ tiếp tục chấn động bởi các cuộc truy sát, cái chết của một quái thai cổ đại khi độ thiên kiếp và tin đồn Thập Quan vương sở hữu Thế Giới thụ non. Thạch Hạo bất ngờ sống sót trồi lên khỏi hồ, bắt hậu duệ Đế Côn hỏi chuyện rồi đánh tan đội sinh linh Chân Thần canh giữ. Sau đó hắn đặt đỉnh lớn bên hồ nấu long tước, voi vàng và giao long, cố ý truyền tin ra ngoài để khiêu khích các thế lực từng chờ hắn chết. Tin Hoang sống lại nhanh chóng chấn động Tiên cổ và Ba ngàn châu, đồng thời khiến khả năng hắn tu thành luồng tiên khí thứ ba trở thành mối lo thực tế."},{"chuong":944,"tieuDe":"Hung Hăng","tomTat":"Sau thời gian trọng thương và khổ luyện trong Hỗn Độn Văn hồ, Thạch Hạo sống sót trở về bên hồ nước đen với pháp lực cường thịnh. Hắn trấn áp các sinh linh từng truy sát mình, dùng gân Cầu Long xâu họ lại làm thức ăn dự trữ nhưng tha cho người không liên can. Thạch Hạo phát hiện và giết đệ nhất sát thủ Thiên quốc đương đại, đồng thời đoạt tinh hoa của các cường giả Ma Quỳ viên để ăn. Hắn còn bắt thần đằng của Thái Dương thần cung nhai như mía, khiến các thế lực ngoại giới phẫn nộ. Cuối cùng, Hoàng kim cổ tượng, Thiên Thần Cầu Long tộc, Long Tước và Mã Nguyên xé hư không giáng lâm, nhưng Thạch Hạo vẫn dùng ngà voi, giáp vảy Cầu Long và chân vũ Long Tước để khiêu khích, rồi gọi thêm các đối thủ khác tới đối đầu."},{"chuong":945,"tieuDe":"Hơi Hơi Gài Bẫy","tomTat":"Thạch Hạo công khai chế giễu Mã Nguyên và chống lại bí thuật áp chế thần thức của ông ta, khiến các Thiên Thần nhận ra Đạo thương của hắn đã khỏi hẳn. Nhóm Thiên Thần bao vây hồ nước đen, phong tỏa hư không để bắt và chiếm lấy thân thể Thạch Hạo. Thạch Hạo tung một quyền xuống hồ Hỗn Độn Văn, đánh thức đàn muỗi thần, ấu trùng Chân Thần và các sinh linh mang hình thái cổ văn hỗn độn, rồi dùng Vạn Linh đồ cùng giáp trụ nghi liên quan tới Lôi Đế để tiến vào hồ. Các Thiên Thần bị đàn sinh linh trong hồ phản kích, Cầu Long, Long Tước, Mã Nguyên và Cổ viên lần lượt trọng thương, buộc phải tháo chạy, khiến cuộc săn bắt đầu tiên thất bại. Tin tức lan ra làm chấn động hơn nửa Tiên cổ. Sau một ngày, Mã Nguyên, Hoàng kim cổ tượng, Cầu Long, Cổ viên, Tỳ Hư và Đế Côn tập hợp lại tại Ám giới bên hồ, còn Thạch Hạo ló đầu lên khiêu khích và tuyên bố sẽ tiễn toàn bộ bọn chúng lên đường."},{"chuong":946,"tieuDe":"Ngược Trời Giết Người","tomTat":"Ám giới tụ tập hơn mười vạn người để theo dõi nhiều Thiên Thần liên thủ truy sát Thạch Hạo. Đế Côn, Mã Nguyên, Hoàng kim cổ tượng, Cổ viên, Tỳ Hưu cùng những Thiên Thần khác công kích hồ nước đen, kích động đàn muỗi để gây áp lực lên hắn, rồi phong tỏa sơn mạch và cắt lìa hư không mang hắn rời khỏi tiểu thiên thế giới. Hai Hỗn độn cổ văn cùng đàn muỗi đuổi theo qua nhiều tiểu thiên thế giới, còn các Thiên Thần chuẩn bị luân phiên phá hủy Thần phù bảo vệ. Trong tuyệt cảnh, Thạch Hạo vận chuyển toàn bộ thần lực, dùng Bảo thuật Lôi Đế cưỡng ép dẫn động thiên kiếp trong thời đại vốn không có thiên kiếp. Thiên phạt và nguyền rủa cuốn các Thiên Thần vào, khiến Mã Nguyên, Đế Côn và Hoàng kim cổ tượng bị thương nặng, trong đó Hoàng kim cổ tượng còn bị đánh gãy một chiếc ngà. Người xem chiến ở Tiên cổ và Ba ngàn châu chấn động trước việc Thạch Hạo nghịch chuyển tình thế."},{"chuong":947,"tieuDe":"Thiên Kiếp","tomTat":"Thạch Hạo dùng sinh mệnh khơi dậy một thiên kiếp tuyệt diệt, loại thiên kiếp đã hơn một kỷ nguyên chưa xuất hiện, để đối phó các đại Thiên Thần. Thiên kiếp mang theo nguyền rủa đậm đặc, khiến Mã Nguyên, Long Tước và những Thiên Thần khác chịu thương tổn nghiêm trọng. Hai con Hỗn độn cổ văn bị kích thích đã niêm phong khu vực, dùng vòi tấn công những kẻ tìm cách phá vây; Long Tước chết đầu tiên sau khi huyết nhục hóa thành nước mủ và nguyên thần bị phá vỡ. Cầu Long mất nửa thân, còn Tỳ Hưu và Cổ viên cùng nó tiếp tục xung kích tìm đường thoát. Thạch Hạo dù bị đánh đến lộ xương vẫn sống sót vì cơ thể chưa từng ẩn chứa nguyền rủa, rồi chủ động mang trung tâm thiên kiếp lao tới Mã Nguyên. Cuối cùng, hắn đạp vỡ xương sọ Mã Nguyên, khiến nguyên thần nổ tung và hình thần đều diệt."},{"chuong":948,"tieuDe":"Truy Sát Thiên Thần","tomTat":"Sau cái chết của Long Tước và Mã Nguyên, các Thiên Thần còn lại cố phá vòng vây trong khi nguyền rủa tiếp tục ăn mòn thân thể. Cầu Long bị Hỗn độn cổ văn xuyên thủng Thiên linh cái, còn Hoàng kim cổ tượng bị nguyền rủa làm nguyên thần nổ tung, khiến bốn đại Thiên Thần đều bỏ mạng. Hỗn độn cổ muỗi rời đi, còn Thạch Hạo dùng Phá Giới phù vượt qua giới bích để truy sát Tỳ Hưu, Cổ viên và Đế Côn. Tỳ Hưu chết tại nơi cư trú của tộc, Cổ viên bị thiên kiếp cùng nguyền rủa đánh tan nguyên thần, còn Đế Côn tiết lộ mưu đồ của Tiên điện tại Tiên cổ trước khi hình thần câu diệt. Xung kích từ trận chiến giúp Thạch Hạo giải khai tiềm năng, thân thể tự chữa trị và sắp tiến vào lĩnh vực Chân Thần. Thiên kiếp tiếp tục tăng mạnh, xuất hiện những tia chớp mang hình thái cổ mộc và sinh linh."},{"chuong":949,"tieuDe":"Đại Đạo Trát Đao","tomTat":"Thạch Hạo đứng trong biển sấm và đẩy tu vi Thần Hỏa lên đại viên mãn, chuẩn bị xung kích Chân Thần cảnh. Trong thiên kiếp, biển sấm ngưng tụ một sinh linh Thao Thiết khiến hắn bị thương, nhưng hắn vẫn xuyên thủng mi tâm đối thủ và nhận ra luồng tiên khí thứ ba đang thành hình. Sau đó, Thiên bia vàng óng hiện ra rồi lộ Đại đạo Trát đao, thanh đao cắt thân thể và nguyên thần của Thạch Hạo thành hai nửa, đồng thời làm gián đoạn luồng tiên khí mới ngưng tụ. Nhớ lại lời Bạch Quy, Thạch Hạo dùng hai luồng tiên khí nối lại thân thể và thi triển áo nghĩa Luân hồi để chống trả. Đại đạo Trát đao hóa lại thành Thiên bia rồi biến mất, luồng tiên khí thứ ba hoàn chỉnh, còn Thạch Hạo phá vỡ trói buộc và đột phá Chân Thần cảnh."},{"chuong":950,"tieuDe":"Tắm Rửa Lôi Kiếp Viên Mãn","tomTat":"Thạch Hạo hoàn thành thăng hoa sinh mệnh, tu thành luồng tiên khí thứ ba và đột phá Chân Nhất cảnh, đạt Chân Thần trung kỳ. Thiên kiếp hóa thành loạn quân kỵ sĩ và hung thú Thái cổ, nhưng hắn dùng pháp môn Côn Bằng cùng Kim Tuyền Ba Văn Công để tiêu diệt toàn bộ địch thủ. Ba luồng tiên khí giúp hắn chữa trị thân thể giữa biển sấm, sau đó hắn lần lượt phá các cổ bảo lôi kiếp gồm cổ điện bằng đồng, tháp chín tầng, chuông chữ Vô và nhiều bảo vật khác. Thạch Hạo tiếp tục chiến đấu trong nhà giam nguyên thần giữa dòng sông thời gian, vượt qua chín tầng trời rồi đánh tan tầng thứ mười. Ở phần cuối lôi vực, hắn chịu dư âm Trảm Tiên đài, thu gom cổ dược lôi điện và cuối cùng bò tới ao vàng cạnh thần thụ cổ để uống Lôi Kiếp dịch."},{"chuong":951,"tieuDe":"Tiến Hóa","tomTat":"Sau khi vượt qua chín tầng lôi kiếp và tiến vào khu vực thứ mười, Thạch Hạo gần như bị hủy cả thân thể lẫn nguyên thần, chỉ còn ba luồng tiên khí duy trì sinh mệnh. Hắn uống Lôi Kiếp dịch màu vàng trong tiên trì cổ, nhờ sinh cơ mạnh mẽ của bảo dịch mà huyết nhục, xương cốt và nguyên thần dần được tái tạo. Một nhóm kỳ tài ba ngàn châu cùng dân bản địa nhân lúc hắn suy yếu đồng loạt dùng binh khí tập kích để cướp cơ duyên, nhưng thiên kiếp lập tức phản kích, phá nát binh khí và giết hơn nửa số người ra tay. Đả Thần Thạch và Tào Vũ Sinh hiện thân bảo vệ Thạch Hạo, còn Thỏ nhỏ cầu xin Thiên Thần tuyệt đỉnh của Bát Tí Hồn tộc trừng trị nhóm người vẫn âm mưu sát hại hắn. Vị Thiên Thần cuốn hơn mười kẻ vào biển sấm, khiến họ lần lượt bị lôi kiếp oanh sát. Thạch Hạo uống hết một phần ba ao bảo dịch, hoàn tất quá trình thoát thai hoán cốt sau khi trở thành Chân Thần và ổn định Đạo quả. Khi biển sấm tan hết, hắn dùng bình ngọc thu lấy toàn bộ Lôi Kiếp dịch còn lại trước ánh mắt thèm muốn của những người quan sát."},{"chuong":952,"tieuDe":"Khách Quý Của Thiên Thần","tomTat":"Sau khi tiên trì cổ biến mất cùng thiên kiếp, Thạch Hạo xác nhận mình đã tiến vào Chân Thần cảnh trung kỳ và sức mạnh nguyền rủa trong cơ thể cũng hoàn toàn tiêu tan. Những người quen tới hội ngộ, trong khi nhiều Thiên Thần bản địa mang theo cả thiện ý lẫn sát ý vây quanh hắn. Thạch Hạo dùng Lôi Kiếp dịch thử nghiệm trên Thiên Thần tuyệt đỉnh của Bát Tí Hồn tộc, giúp ông hóa giải hoàn toàn nguyền rủa, còn hai Thiên Thần Nhân Mã tộc và Cổ Ma tộc cũng cảm nhận tai họa suy yếu sau khi uống một ly. Phát hiện này khiến dân bản địa chấn động và dẫn tới một cuộc tranh cướp bình ngọc, nhưng lượng bảo dịch còn lại đã không đủ nửa ly. Thạch Hạo nhắc lại chuyện mình từng bị người của Nhân Mã tộc và Cổ Ma tộc chặn giết, khiến hai Thiên Thần cao tầng của các tộc này hối hận và tức giận. Cuối cùng, hắn chỉ ra rằng mình còn có thể tiếp tục trưởng thành và độ kiếp trong tương lai, biến bản thân thành hi vọng lâu dài để hóa giải nguyền rủa. Các Thiên Thần lập tức đổi từ đòi giết sang bảo vệ, tranh nhau mời hắn làm khách và thậm chí dùng hôn sự để lôi kéo."},{"chuong":953,"tieuDe":"Bánh Ngon Trái Ngọt","tomTat":"Sau khi Thạch Hạo vượt qua thiên kiếp và chứng tỏ khả năng hóa giải nguyền rủa, các Thiên Thần từ bỏ ý định vây giết rồi chuyển sang tranh nhau lôi kéo hắn. Nhiều cường tộc dùng công chúa, mỹ nhân, thánh địa tu luyện và tài nguyên làm điều kiện, nhưng Thạch Hạo từ chối Cổ Ma tộc cùng Nhân Mã tộc và chọn tới thánh địa của Bát Tí Hồn tộc vì nơi đó còn một cành cây Tế Linh. Cùng lúc, tin hắn vượt qua thiên kiếp mạnh nhất và có thể giải nguyền rủa lan khắp Tiên cổ, khiến các tộc phái người tìm gặp. Ở ba ngàn châu, một tia điện từ vực ngoại đánh thức tế đàn cổ cùng Tiên đạo tàn trận, làm các Giáo chủ lo ngại sinh linh không thuộc thế giới này sắp giáng lâm. Thạch Hạo cùng các đồng bạn tiến vào Tế Linh giới, vùng cấm địa do mười bộ lạc bảo vệ, rồi tìm thấy hồ nước và những di tích thờ phụng cây Liễu. Pháp tướng Liễu Thần thức tỉnh thành cây đại thụ che trời và truyền âm cho Thạch Hạo. Nàng xác nhận hắn là người thứ hai đánh thức mình, còn người đầu tiên từng mang theo một chiếc đỉnh dính máu lượn lờ mẫu khí thiên địa."},{"chuong":954,"tieuDe":"Vị Khách Thần Bí Tới","tomTat":"Thạch Hạo nhận ra dấu ấn của chiếc đỉnh cổ nhuốm máu từng xuất hiện dưới Hắc Uyên, đồng thời ghi nhớ hình dáng ba chân hai tai cùng mẫu khí và hỗn độn bao quanh nó. Trước miếu cổ, hắn gặp cành cây vàng của Liễu Thần và được biết đây không phải chân thân, ký ức đã thiếu hụt và sắp tan biến vì từng sử dụng sức mạnh vượt quá cực hạn. Cành cây tiết lộ người bí ẩn liên quan mang họ Diệp, đã rời khỏi di địa Tiên cổ, rồi dẫn dắt Thạch Hạo xác định mục tiêu tại Chân Nhất cảnh là cảm ngộ sinh tử và sinh mệnh. Liễu Thần sau đó truyền cho hắn cổ thuật từng là bảo thuật của mình trong kỷ nguyên Tiên cổ, giúp hắn thu hoạch lớn khi quan sát sự diễn biến và lột xác của pháp môn. Cùng lúc tại Trung châu, tế đàn cổ được sức mạnh từ hư không kích hoạt, khiến tàn trận Tiên đạo thức tỉnh và mở ra một thông đạo bạc. Ba người trung niên cùng một nhóm nam nữ trẻ tuổi có khí tức xa xưa bước ra, khiến các đại giáo thượng giới kinh động và phải giải nghĩa loại cổ ngữ họ sử dụng. Một người trẻ tuổi sở hữu tiên khí công khai khinh thị cường giả bản giới, cuối cùng tuyên bố muốn một mình luận bàn với toàn bộ Thiên Thần thượng giới."},{"chuong":955,"tieuDe":"Hồn Đảo","tomTat":"Thạch Hạo cùng các Thiên Thần và đồng bạn rời tổ địa Tế Linh, tới Hồn đảo dự tiệc mừng hắn vượt lôi kiếp. Hắn hứa sẽ tiếp tục lấy Lôi Kiếp dịch nếu còn độ kiếp, khiến các Thiên Thần bản địa nhận ra rằng bảo vệ hắn là cơ hội để họ hóa giải nguyền rủa. Trong lúc Thỏ nhỏ gây náo loạn vì cắn lá của một cây thần dược đã thành tinh, Bát Tí Hồn tộc cung cấp cho Thạch Hạo manh mối về Thánh Nhân mộc. Thạch Hạo cũng truy hỏi đại diện Nhân Mã tộc và Cổ Ma tộc về những Thiên Thần từng chặn giết mình, nhưng hai người chỉ muốn dùng thiên tài địa bảo bồi thường. Một tiếng rít kinh khủng sau đó dẫn mọi người tới lão tổ Bát Tí Hồn tộc, cường giả vượt Thiên Thần cảnh đã sống gần năm vạn năm nhưng bị nguyền rủa làm mất thần trí và phải giam trong đại trận. Thạch Hạo lấy phần Lôi Kiếp dịch còn giấu trong đỉnh ngọc, còn Bát Tí Hồn tộc dùng Trấn Hồn thạch giúp lão tổ tạm tỉnh trước khi uống bảo dịch. Khói đen nguyền rủa trào khỏi cơ thể lão tổ rồi bốc cháy, chứng minh phương pháp cứu chữa có hiệu quả. Nhận thấy Tiên cổ có thể sắp mở, Thạch Hạo quyết định cứu thêm các cường giả cấp Giáo chủ để tập hợp lực lượng đánh ra ngoài."},{"chuong":956,"tieuDe":"Thiên Kiếp Lại Hiện","tomTat":"Thạch Hạo yêu cầu các tộc giữ kín bí mật tại cổ địa Tế linh, dùng ba luồng tiên khí che giấu thiên cơ rồi rời đi. Lôi Kiếp dịch giúp đệ nhất cao thủ Bát Tí Hồn tộc tỉnh táo hơn nhưng chưa thể hóa giải hết nguyền rủa, nên ông tiếp tục tự phong ấn. Tin tức về người dẫn thiên kiếp ban đầu gọi tên Cô Kiếm Vấn, sau đó xác định người vượt kiếp là Cô Kiếm Vân, đệ tử Kiếm cốc. Cô Kiếm Vân thành công bước vào lĩnh vực Chân Thần rồi phân phát Lôi Kiếp dịch để lôi kéo các Thiên Thần, khiến Mã Dược và Ma Lạc công khai đứng về phía hắn và chế giễu Thạch Hạo. Các Thiên Thần nhanh chóng phát hiện bảo dịch của Cô Kiếm Vân phần lớn mang màu tím và không thể làm suy yếu nguyền rủa. Thạch Hạo tiết lộ mình từng độ kiếp từ Tôn giả cảnh và thu được cả một ao Lôi Kiếp dịch màu tím, làm Cô Kiếm Vân và những người ủng hộ hắn bị đả kích. Sau đó nhiều người tiếp tục thử dẫn thiên kiếp nhưng đều thất bại, hình thần俱 diệt."},{"chuong":957,"tieuDe":"Bão Táp Nổi","tomTat":"Làn sóng độ kiếp lan rộng khắp Tiên cổ nhưng phần lớn người thử vượt kiếp đều chết, càng làm nổi bật thành tích của Thạch Hạo. Nhân Mã tộc và Cổ Ma tộc lần lượt mang thần đan cùng thanh mâu đồng đến tìm cách làm hòa với hắn, nhưng Thạch Hạo không hứa giao Lôi Kiếp dịch hay giúp Ma Lạc hóa giải nguyền rủa. Mã Dược và Ma Lạc vẫn giữ địch ý, trong đó Ma Lạc còn tính chuyện cướp Lôi Kiếp dịch. Cô Kiếm Vân là người duy nhất ngoài Thạch Hạo được xác nhận sống sót sau độ kiếp, còn Tào Vũ Sinh tuyên bố muốn tự mình thử vượt qua thiên kiếp. Đạo cung vàng và võ đài Tiên cổ đồng thời xuất thế tại Vân giới, khơi lại những chiến tích của Ninh Xuyên, Thập Quan vương và Trường Cung Diễn. Sau đó Trích Tiên, Ninh Xuyên và Thập Quan vương lần lượt dẫn phát thiên kiếp tại Hung sào, di tích Tiên cổ bị nguyền rủa và Tử Vong hải, khiến bão táp lan khắp Tiên cổ."},{"chuong":958,"tieuDe":"Ngưng Huyết Tộc","tomTat":"Các cấm khu trong Tiên cổ im ắng sau lôi kiếp, đồng thời lan truyền tin đồn Ninh Xuyên và Thập Quan vương đã gặp nạn. Thạch Hạo tiếp tục tu hành tại tổ địa Tế linh, trong khi nhiều bộ lạc tìm đến vì muốn có Lôi Kiếp dịch. Ngân Khôi cùng hai Thiên Thần áo bạc của Bộ tộc Ngân Huyết ma thụ đến Hồn đảo để lôi kéo rồi uy hiếp Thạch Hạo. Ngân Khôi bóp nát ngọc bài triệu hồi cổ tổ, khiến linh thân cổ tổ giáng lâm và làm Hồn đảo sụp đổ. Đệ nhất cường giả Bát Tí Hồn tộc xuất hiện với thần trí đã khôi phục, sau đó cùng cổ tổ Ngân Huyết ma thụ rời đi. Thạch Hạo đánh trọng thương Ngân Khôi và hai Thiên Thần áo bạc rồi ném họ khỏi Hồn đảo. Vài ngày sau, Võ đài Tiên đạo hoàn toàn hiện ra, đồng thời một vết rách hư không khổng lồ xuyên qua các tiểu thiên thế giới."},{"chuong":959,"tieuDe":"Pháp Môn Của Liễu Thần","tomTat":"Một vết rách xuất hiện tại khu vực không người của Tiên cổ, khiến các Giáo chủ thử phá giới bích để mở đường cho ngoại giới tiến vào. Chuông Minh nguyệt bị pháp tắc thần bí đánh hỏng, còn đòn công kích liên thủ chỉ khiến khe nứt xuyên qua tiểu thiên thế giới và làm giới bích chấn động. Tại Vân giới, Đạo cung vàng và võ đài Tiên đạo mở ra với điều kiện người tham chiến phải thắng liên tiếp một trăm trận mới được nghỉ, và Địa ngục khuyển ba đầu là kẻ đầu tiên lên đài. Thạch Hạo quyết định tranh thủ đoạt vị trí dẫn đầu trước khi Giáo chủ ngoại giới giáng lâm. Hắn tu hành pháp của Liễu Thần bằng cách thiêu đốt tinh nguyên, khiến thân thể khô quắt và tinh lực suy kiệt. Dù được người của Bát Tí Hồn tộc tìm cách cứu trợ, Thạch Hạo vẫn từ chối bổ sung tinh lực rồi xuất hiện tại Vân giới, làm quần hùng chấn động."},{"chuong":960,"tieuDe":"Thắng Liên Tiếp","tomTat":"Thạch Hạo xuất hiện tại võ đài tranh bá Tiên cổ và lập tức khiến toàn trường chú ý vì chiến tích vượt qua thiên kiếp mạnh nhất cùng việc khiến bảy đại Thiên Thần bỏ mạng, dù thân thể đang suy kiệt nghiêm trọng. Địa ngục khuyển ba đầu dùng Lửa địa ngục, Nước hoàng tuyền và mắt dọc để đánh bại Dạ Xoa cánh vàng, thiêu chết Cổ thụ Thiết Huyết và thắng ba mươi trận trước khi bị Tỳ Hưu chấm dứt chuỗi thắng. Thạch Hạo lên đài, bóp nát bí bảo của Tỳ Hưu, dùng cành liễu màu vàng xuyên thủng trái tim nó nhưng tha mạng và đưa nó rời khỏi võ đài. Sau đó hắn thiêu đốt bản nguyên sinh mệnh để duy trì chiến lực, lần lượt vượt qua các đối thủ và bắt đầu giết người từ trận thứ mười tám. Dù bị các sinh linh có địch ý tổ chức bốc thăm để tiêu hao, Thạch Hạo vẫn thắng liên tiếp tám mươi lăm trận. Thiểm Điện Tử xuất hiện ở trận thứ tám mươi sáu, dùng hàng chục bí bảo tấn công nhưng cuối cùng bỏ chạy và bị Thạch Hạo dùng cành liễu màu vàng xuyên thủng thân thể, phá nát nguyên thần. Sau đó Thạch Hạo tiếp tục thắng các trận thứ chín mươi mốt và chín mươi hai trong sự kinh sợ của toàn trường."},{"chuong":961,"tieuDe":"Không Ai Có Thể Ngăn Cản Nổi","tomTat":"Dù trọng thương và tinh lực gần cạn, Thạch Hạo vẫn đánh bại Chu Yếm vương trong trận thứ chín mươi lăm, nhưng tha mạng cho đối thủ vì nhớ đến Bóng Lông ở hạ giới. Hắn tiếp tục dùng bảo thuật Lôi Đế giết một Chân Thần khung xương trắng, cho thấy bản thân đang phải kết thúc các trận đấu nhanh hơn vì thương thế nguy cấp. Cô Kiếm Vân của Kiếm cốc xuất hiện, công khai ham muốn tiên kiếm Đại La nhưng từ chối giao chiến với một người đang hấp hối. Đằng xà sau đó lên đài, bị Thạch Hạo dùng Thượng Thương Chi Thủ kéo đứt thân thể rồi lấy tiên kiếm Đại La đâm xuyên hư không để giết chết. Ở trận thứ chín mươi tám, Huyền quy màu đen bị chém đôi mai rùa và vội nhận thua nên được tha mạng. Quái thai cổ đại bước vào trận thứ chín mươi chín với ý định tiêu hao khí huyết của Thạch Hạo, nhưng bị Luân Hồi làm già yếu rồi bị kết liễu. Sau khi giành chiến thắng liên tiếp đến trận thứ chín mươi chín, Thạch Hạo trực tiếp gọi Cô Kiếm Vân lên đài."},{"chuong":962,"tieuDe":"Quét Ngang Địch Thủ","tomTat":"Cô Kiếm Vân từ chối giao chiến vì cho rằng đạo cơ và bản nguyên của Thạch Hạo đã bị tổn thương đến mức không còn sống được lâu, nhận định này còn được một quái thai cổ đại dùng Thiên nhãn xác nhận. Không ai dám nhận trận thứ một trăm, giúp Thạch Hạo hoàn thành chuỗi thắng, nhưng hắn không rời đi mà tiếp tục thủ đài để sớm tranh vương tọa cuối cùng. Khi các phe thù địch liên tục phái người lên tiêu hao hắn, Thạch Hạo dùng Luân Hồi biến một đối thủ thành xương khô rồi đại khai sát giới, lần lượt vượt qua các mốc hai trăm, ba trăm, bốn trăm và năm trăm trận thắng. Tình trạng tinh lực héo tàn và bản nguyên bốc cháy thực chất là giai đoạn nguy hiểm trong Bảo thuật Liễu Thần, buộc người tu phải tự diệt trước khi tái lập sức sống nhưng cũng có thể khiến hắn tọa hóa nếu thất bại. Sau chiến thắng thứ năm trăm, võ đài phát sáng chiếu lên Thạch Hạo như sự ca ngợi và công nhận. Cùng lúc tại Trung châu, các Giáo chủ chia lực lượng giữa khe lớn của di địa Tiên cổ và trận pháp Tiên đạo. Một người trẻ tuổi tự nhận đến từ Thiên đã thắng liên tiếp tám mươi mốt trận trước các Thiên Thần, hiển hóa tiên khí thành hoa Đại đạo và ngạo nghễ thách tất cả cùng tiến lên."},{"chuong":963,"tieuDe":"Khiêu Chiến","tomTat":"Sau năm trăm trận thắng liên tiếp của Thạch Hạo, nhiều phe dùng thiên tài địa bảo thuê kỳ tài ba ngàn châu và dân bản địa Tiên cổ tiếp tục lên đài tiêu hao hắn, trong khi Cô Kiếm Vân vẫn từ chối giao chiến. Thạch Hạo vừa phải nghênh chiến vừa thiêu đốt bản thân để hoàn thành sự lột xác từ pháp Liễu Thần, nên dần rơi vào tình trạng tinh huyết gần cạn. Hắn bị một cường giả bắn trúng vai nhưng dùng pháp môn Côn Bằng ngưng tụ kiếm lông chim chém đôi đối thủ, sau đó tiếp tục đánh nổ Thương lang thái cổ khi bị cào trúng tay. Ngân Khôn cùng Ma Quỳ viên, Minh thổ, Thiên quốc và nhiều thế lực thù địch treo Đại Niết Bàn đan, binh khí chuẩn Giáo chủ cùng bảo đan chứa thần dược để thuê người giết Hoang. Dù nhiều lần lảo đảo và gặp nguy hiểm, Thạch Hạo vẫn vượt qua trận thứ tám trăm, phá tiền lệ của quái thai cổ đại nhưng chưa được võ đài công nhận là người thắng cuối cùng. Nhận thấy mình không thể tiếp tục và cần hoàn thành tu luyện, hắn chủ động bước xuống võ đài. Các phe thù địch lập tức xúi giục di dân Tiên cổ và thiên tài ba ngàn châu khiêu chiến hắn ngoài đài. Thạch Hạo ngăn người Bát Tí Hồn tộc can thiệp rồi tuyên bố sẽ tự mình đại khai sát giới."},{"chuong":964,"tieuDe":"Đại Khai Sát Giới","tomTat":"Dù đang trọng thương, Thạch Hạo rút tiên kiếm Đại La chém chết Thần viên màu vàng rồi dùng kiếm quang thanh toán hàng chục kẻ ẩn trong đám đông kích động giết mình. Ngân Khôn, hậu duệ bảy đại Thiên Thần và tàn dư nhiều thế lực tiếp tục gọi tử sĩ, treo thưởng và lôi kéo cao thủ bản địa vây ép hắn, trong khi Bát Tí Hồn tộc cùng các cường tộc khác công khai bảo vệ hắn. Thạch Hạo quyết định giải phóng và thiêu đốt toàn bộ tinh lực, kể cả phần tinh hoa Chí Tôn huyết còn niêm phong, để luyện thân theo pháp môn cây khô gặp mùa xuân của Liễu Thần. Sức chiến đấu tăng vọt giúp hắn giết hàng loạt tử sĩ, chém chết Ngân Khôn và dùng Luân Hồi khiến hậu duệ bảy đại Thiên Thần mất hết thanh xuân rồi hóa thành xương trắng. Hắn tiếp tục truy sát tàn dư Thần miếu, Ma Quỳ viên, Hỏa Vân động cùng những kẻ từng kích động, khiến hơn một nghìn thi thể chất đầy chiến trường; các Thiên Thần định can thiệp đều bị phe bảo vệ hắn ngăn lại. Sau cuộc tàn sát, sinh cơ của Thạch Hạo hoàn toàn biến mất, nhưng không lâu sau một tia sinh cơ mới xuất hiện và cánh tay khô quắt chuyển thành màu vàng óng, báo hiệu quá trình tái sinh đã bắt đầu."},{"chuong":965,"tieuDe":"Cường Giả Đều Xuất Hiện","tomTat":"Thạch Hạo dần phục hồi khỏi trạng thái khô quắt tưởng như đã tọa hóa, hào quang vàng lan khắp thân thể và sinh cơ tái hiện. Một nam Thiên Thần của Ngân Huyết Ma thụ tộc dùng thần trùy tập kích hắn, nhưng lão Thiên Thần Bát Tí Hồn tộc kịp ngăn cản, đứng ra bảo vệ và giao chiến với đối phương. Trong lúc đó, nhiều cường giả ngoại giới công kích giới bích Tiên cổ, khiến các vết rách hư không rung chuyển và báo hiệu Giáo chủ có thể sắp phá giới tiến vào. Cô Kiếm Vân lên võ đài, không chiến mà thắng nhiều trận rồi tiêu diệt một quái thai tóc xám có khả năng phục sinh chín lần nhờ Vô lượng huyết kinh. Sau đó hắn bị một pháp khí Thiên Thần làm bị thương nhưng vẫn chém chết người sử dụng, trước khi chủ động rời đài để dưỡng thương. Ninh Xuyên xuất hiện và bước lên võ đài, xác nhận đã sống sót sau thiên kiếp, khiến không ai dám khiêu chiến. Thạch Hạo đồng thời phát hiện Diệp Thiên Vũ và Thập Quan vương vẫn còn sống, nhận ra cuộc đại đối quyết giữa các nhân vật đỉnh cao đã tới gần."},{"chuong":966,"tieuDe":"Đại Chiến Chí Tôn","tomTat":"Ninh Xuyên liên tục thủ thắng trên võ đài, vượt qua nhiều đối thủ mang pháp khí Thiên Thần, trong đó có người sử dụng Vô Ảnh đao và một quái thai cổ đại sở hữu nguyền rủa. Sau chiến thắng thứ bốn trăm, hắn chủ động dừng lại để dưỡng sức trước những đối thủ mạnh nhất. Thập Quan vương lên đài, dùng khí hỗn độn tiêu diệt một người mang pháp khí Thiên Thần rồi đối mặt Diệp Thiên Vũ, người đã có duyên gặp gỡ với hắn từ mười đời trước. Hai người quyết đấu bằng bảo thuật Chân Long, đại thần thông Thiên Phượng và nhiều bảo thuật Thập Hung khác. Cùng lúc đó, Thạch Hạo hoàn tất quá trình lột xác khiến toàn thân hóa vàng và nhận lời khiêu chiến của Ninh Xuyên. Võ đài vì thế xuất hiện đồng thời hai cuộc quyết đấu giữa bốn chí tôn trẻ tuổi, mở màn đại chiến Chí Tôn chưa từng có."},{"chuong":967,"tieuDe":"Cuộc Chiến Đỉnh Cao","tomTat":"Trên võ đài, Thập Quan vương giao chiến quyết liệt với Diệp Thiên Vũ, trong khi Thạch Hạo đối đầu Ninh Xuyên bằng thân thể vàng óng hình thành từ pháp của Liễu Thần. Ninh Xuyên triệu hiện chín vị Cổ thần, dẫn sức mạnh nhật nguyệt và tinh tú, còn Thạch Hạo dùng quyền ấn xuyên phá hư không để chống đỡ trong khoảng ngàn lần giao kích. Khi Ninh Xuyên thi triển Nhất nguyên luyện hư không và tạo ra kim đan bằng khí hỗn độn, Thạch Hạo dùng Bí thuật Lôi Đế biến lôi đình thành chòm sao rồi cho nổ tung để phá cấm chế. Ninh Xuyên kinh ngạc vì Thạch Hạo chỉ tu hành một đời nhưng đã có chiến lực sánh với sự tích lũy sáu đời của mình. Thập Quan vương sau đó bộc phát thần uy làm nhiều người dưới đài bị thương, tạm bỏ qua Diệp Thiên Vũ và chen vào trận chiến của hai người. Hắn dùng Long quyền đối đầu Côn Bằng quyền của Thạch Hạo, tạo nên lần va chạm đầu tiên giữa hai Bảo thuật Thập Hung. Sau cú giao phong, Thạch Hạo phát hiện ba luồng tiên khí quanh nắm đấm Thập Quan vương, còn đối phương cũng xem hắn là một địch thủ mới đáng mong đợi."},{"chuong":968,"tieuDe":"Các Thần Tranh Bá","tomTat":"Thập Quan vương liên tiếp thăm dò Ninh Xuyên và Thạch Hạo, khiến võ đài bùng nổ những đợt va chạm làm không gian nứt vỡ. Ninh Xuyên nhận ra Diệp Thiên Vũ chính là người có liên quan đến lần mình suýt chết tại Hung sào, từ đó hai bên quyết toán ân oán bằng Thiên đồ và Đại thần thông Thiên Phượng. Thạch Hạo nhập chiến, dùng Côn Bằng pháp đối đầu Thiên phượng rồi vận dụng thần thông thứ ba chưa hoàn thiện chống lại sức mạnh Thiên Giác Nghĩ của Diệp Thiên Vũ. Khi Ninh Xuyên dùng Thiên đồ định thu luyện Thạch Hạo, Thạch Hạo biến phù văn thành Luân Hồi kiếm để phá giải bằng sức mạnh thời gian. Cô Kiếm Vân lên đài nhưng bị Thạch Hạo dùng tay không áp đảo, sau đó còn bị Trùng Đồng của Thạch Nghị đánh nứt bàn tay. Trường Cung Diễn vừa vượt qua Thiên kiếp cũng xuất hiện để ngăn Cô Kiếm Vân, trong khi chàng trai từng sở hữu một góc Luân Hồi bàn bước lên muốn thử sức hắn. Cuối cùng Tử Viên Phu tuyên bố xuất quan cùng thành tựu mới của Đại Phần Thiên Công, khiến võ đài quy tụ hàng loạt cường giả mạnh nhất và báo hiệu một cuộc đại quyết chiến."},{"chuong":969,"tieuDe":"Thiên Kiêu Hỗn Chiến","tomTat":"Các vương giả đương đại, quái thai cổ đại và cao thủ nhiều phe đồng loạt tiến lên võ đài Tiên cổ, mở ra một cuộc hỗn chiến dữ dội để tranh đoạt tạo hóa. Thập Quan vương dùng Long quyền quét ngang quần hùng, trong khi Cô Kiếm Vân và các cường giả Hỏa Vân động liên kết với Ninh Xuyên, dùng nhiều pháp khí Thiên Thần vây giết Thạch Hạo. Thạch Hạo lấy Vạn Linh đồ phòng ngự rồi vận dụng Côn Bằng pháp, kiếm phù văn Luân hồi và Lôi Đế ấn để phản sát nhiều đối thủ; Trường Cung Diễn cũng bắn rơi Cô Kiếm Vân khỏi võ đài. Một chàng trai từ hạ giới dùng máu đánh thức một góc Luân Hồi bàn, khiến khí hỗn độn áp chế toàn trường, nhưng Thập Quan vương dùng cây nhỏ nghi là Thế Giới thụ và Diệp Thiên Vũ dùng Sừng Thiên Giác Nghĩ để hóa giải. Khi khe nứt hư không mở rộng và báo hiệu người ngoại giới sắp tiến vào, võ đài hình thành cánh cửa cùng truyền tống trận rồi lựa chọn Thạch Hạo vì thành tích tám trăm trận thắng liên tiếp. Thập Quan vương, Diệp Thiên Vũ, Ninh Xuyên và những người khác đồng loạt ngăn cản, buộc Thạch Hạo mặc giáp rách liên quan đến Lôi Đế, cầm Vạn Linh đồ cùng Nghịch long lân và chuẩn bị phá tan vòng vây."},{"chuong":970,"tieuDe":"Liều Mạng Chém Giết","tomTat":"Thạch Hạo bị Thập Quan vương, Diệp Thiên Vũ, Ninh Xuyên cùng nhiều cao thủ dùng hàng loạt chí bảo vây hãm trên võ đài. Hắn dựa vào Vạn Linh đồ, Nghịch long lân và bộ giáp rách có thể hấp thu bản nguyên thiên địa để duy trì chiến lực trước Thế Giới thụ, Sừng Thiên Giác Nghĩ, Luân Hồi bàn và thiên đồ. Tử Viên Phi gia nhập cuộc chiến bằng Đại Phần Thiên Công đã dung hợp cổ hỏa của Chân tiên, nhưng bị ba luồng tiên khí cùng Bảo thuật Liễu Thần của Thạch Hạo áp chế và đánh trọng thương. Thạch Hạo tiếp tục triển khai những cành liễu vàng hóa thành xích thần trật tự, xuyên giết nhiều người đang ngăn cản. Khi võ đài bốc cháy và bắt đầu giải thể, cánh cửa ánh sáng bành trướng, tạo ra cơ hội cuối cùng để hắn thoát khỏi vòng vây. Thạch Hạo thu hồi Vạn Linh đồ và Nghịch long lân, chặt đứt sự trói buộc của Thế Giới thụ rồi thành công tiến vào cánh cửa. Ngay sau đó, Tiên cổ rung chuyển dữ dội, các khe nứt mở rộng và tin người ngoại giới đã xâm nhập khiến toàn bộ sinh linh kinh hãi."},{"chuong":971,"tieuDe":"Rối Loạn","tomTat":"Tin người ngoại giới đã xâm nhập khiến toàn bộ Tiên cổ chấn động, cư dân bản địa vội trở về chuẩn bị còn thiên tài ba ngàn châu tìm cách nghênh tiếp sư môn. Khi phát hiện cánh cửa ánh sáng vẫn tồn tại, Diệp Thiên Vũ tiến vào trước, tiếp đó Thập Quan vương, Ninh Xuyên, Thạch Nghị, Tào Vũ Sinh, Trường Cung Diễn và nhiều quái thai cổ đại đồng loạt tranh đường. Những người đến sau không lập tức tới vùng đất cuối mà phải chạy hàng vạn dặm trên một con đường pháp tắc, nơi Thạch Nghị và Ninh Xuyên còn xảy ra va chạm thần thông. Tại Huyền Minh giới, một chuẩn Giáo chủ thử vượt khe nứt nhưng bị quy tắc Tiên cổ phá hủy nguyên thần và thiêu thân thể thành tro, chứng minh người vượt lĩnh vực Thiên Thần không thể tiến vào. Các Giáo chủ vì thế quyết định hợp lực duy trì tiết điểm và đưa một số Thiên Thần vào tranh đoạt cơ duyên. Tiên điện, Đế tộc, Tây Phương giáo, Minh tộc và Thần miếu công khai tranh suất, trong khi một Thiên Thần Tiên điện tuyên bố sẽ trấn áp Hoang cùng Trích tiên. Ở phía trước tất cả, Thạch Hạo đã một mình tới vùng đất cuối và lặng người quan sát nơi thần bí."},{"chuong":972,"tieuDe":"Vùng Đất Tạo Hóa Của Tiên Cổ","tomTat":"Thạch Hạo tiến vào vùng đất tạo hóa Tiên cổ và chứng kiến vô số tàn cảnh về chiến tranh, thi thể chí cường giả cùng một đại lục tan rã, nhưng phần chân tướng cuối cùng bị một bàn tay màu vàng mang khí tức Tiên đạo xóa mờ. Khi cảnh tượng thần thánh suy tàn thành khói xám và tử khí, hắn không cam lòng quay về mà dùng ba luồng tiên khí, nhiều bảo thuật cùng Lục Hợp thiên công công kích bức tường tuyệt vọng. Bức tường chấp nhận sức mạnh của hắn và mở ra một cánh cửa hình người dẫn tới cầu thang được luyện chế từ các ngôi sao. Thạch Hạo vượt qua hư vô, tinh không và những cơn gió dữ để bước lên chín tầng trời. Tại đó, hắn phát hiện một vùng đất đỏ sẫm đầy mộ cổ cùng cung điện dưới lòng đất chứa nhiều quan tài ngọc. Các quan tài ban đầu hiện ra những thi thể không đầu có máu vẫn phát sáng và thân thể không mục nát. Sau lời chất vấn của Thạch Hạo, những thi thể đột ngột biến mất, thay vào đó là sách cổ bằng ngọc thạch cùng các tiên chủng thần bí."},{"chuong":973,"tieuDe":"Được Tạo Hóa","tomTat":"Thạch Hạo phát hiện những thi thể trong các quan tài ngọc đã được thay bằng Đạo thư và tiên chủng thuộc hệ thống tu luyện từ hơn một kỷ nguyên trước, nhưng hắn không thể mở bất kỳ quan tài nào. Huyết dịch và sinh cơ còn sót lại trên những thi thể không đầu khiến hắn nghi ngờ họ từng là Tiên hoặc cường giả cấm kỵ, đồng thời nhớ đến các đầu lâu từng thấy trên con thuyền đen nhuốm máu. Đi đến cuối khu truyền thừa, hắn tìm thấy một tế đàn cổ rộng lớn và thuận lợi lấy được hộp ngọc duy nhất được đặt làm cống phẩm. Dấu ấn trong hộp lập tức yêu cầu người lấy phải có tư cách, còn tế đàn giữ chặt hai chân hắn rồi biến thành một chiếc đỉnh luyện hóa. Thạch Hạo vận dụng Chí Tôn thuật, thần thông của Thập Hung và pháp môn của Liễu Thần để chống thiên lôi, hỏa diễm, thái âm thủy, gò đất hỗn độn, Thế Giới thạch cùng các đòn công kích pháp tắc. Dù thân thể nhiều lần bị đánh nát và xương cốt gãy vụn, hắn vẫn tái tạo hình thể nhờ pháp môn của Liễu Thần và cuối cùng sống sót vượt qua cửa ải trong tình trạng trọng thương."},{"chuong":974,"tieuDe":"Hoàn Toàn Khác Với Tất Cả Mọi Người","tomTat":"Thạch Hạo hồi phục sau thương thế tại vùng đất tạo hóa, khôi phục tinh huyết đến đỉnh cao và tiến vào Chân Thần hậu kỳ, gần đạt viên mãn. Hắn vẫn không đủ đạo hạnh để mở hộp ngọc hoặc lấy truyền thừa từ những quan tài cổ quanh tế đàn. Diệp Thiên Vũ, Thập Quan vương, Ninh Xuyên, Thạch Nghị, Tào Vũ Sinh và Trường Cung Diễn lần lượt được các quan tài lựa chọn, trong khi Thạch Hạo cố ý giao chiến với Ninh Xuyên để che giấu hộp ngọc và cản đối thủ nhận tạo hóa. Tin giới bích bị phá và cường giả ngoại giới tiến vào Tiên cổ khiến mọi người phải tính đường rời đi. Những trường hợp người chưa tu ra tiên khí nổ tung khi nhận sách ngọc cho thấy tiên khí là điều kiện thiết yếu để tiếp nhận truyền thừa. Khi một sách ngọc quay lại quan tài và làm phong ấn suy yếu, Thạch Hạo dùng toàn lực nhấc bổng quan tài ấy. Thay vì chỉ lấy kinh thư hoặc tiên chủng như những người khác, hắn khiêng cả quan tài rời khỏi khu cổ địa."},{"chuong":975,"tieuDe":"Giá Lâm","tomTat":"Rời cung điện dưới lòng đất và khu vực mộ Tiên, Thạch Hạo trở lại bức tường tuyệt vọng, ẩn trên con đường không gian màu vàng để phục kích những người mang tạo hóa trở về. Hắn dùng quan tài ngọc đánh ngất đối thủ và cướp vật tùy thân, nhưng một kinh thư kỳ dị đã tự bao phủ tiên chủng rồi xuyên hư không biến mất. Khi Ninh Xuyên và Cô Kiếm Vân xuất hiện, Thạch Hạo đánh Cô Kiếm Vân trọng thương, khiến ngọc thư cùng tiên chủng bay ra, song Ninh Xuyên kịp dùng vòng tay và bí thuật cứu người rút lui trước sự vây ép của Thạch Nghị, Trường Cung Diễn và Tào Vũ Sinh. Cùng lúc đó, sáu Thiên Thần từ Huyền Minh giới vượt qua giới bích, bắt một dân bản địa dò hỏi tình hình rồi tiến tới tiểu thiên thế giới có võ đài. Thạch Hạo, Diệp Thiên Vũ và Thập Quan vương lần lượt trở lại võ đài nhưng bị lực lượng ngoại giới phong tỏa, yêu cầu công bố và giao nộp thu hoạch. Thập Quan vương công khai chống lại sự ép buộc, còn một Chân Thần chỉ tay yêu cầu Thạch Hạo hạ quan tài ngọc xuống. Thạch Hạo đáp lại bằng một cái búng tay, khiến Chân Thần nổ tung ngay trước mặt một Thiên Thần."},{"chuong":976,"tieuDe":"Lập Uy","tomTat":"Sáu Thiên Thần ngoại giới phong tỏa võ đài, ép các thiên tài giao nộp quan tài ngọc và Đạo thư, nhưng Thạch Hạo cùng những người khác kiên quyết chống lại. Thập Quan vương giết kẻ tiết lộ tin tức về thạch thư, sau đó Thạch Hạo, Diệp Thiên Vũ, Thạch Nghị, Thập Quan vương và các thiên tài vận dụng chí bảo đánh thủng vòng vây. Nhờ cổ tổ Bát Tí Hồn tộc bí mật chỉ đường, Thạch Hạo dùng Tiên kiếm Đại La chém hư không và trốn về Hồn đảo. Khi thêm sáu Thiên Thần giáng lâm, tổng cộng mười hai kẻ xâm nhập bắt đầu truy lùng Hoang và cướp đoạt tạo hóa trên khắp Tiên cổ. Thạch Hạo thuyết phục cổ tổ Bát Tí Hồn tộc liên thủ bằng lời hứa thu thập thêm Lôi Kiếp dịch để cứu những cổ tổ bản địa đang chịu nguyền rủa. Cổ tổ đồng ý, phong ấn bốn Thiên Thần ngoại giới rồi giao cho Thạch Hạo dùng Tiên kiếm Đại La chém chết cả thể xác lẫn nguyên thần, qua đó lập uy trước toàn Tiên cổ."},{"chuong":977,"tieuDe":"Khúc Nhạc Dạo Trước Cơn Sóng Dữ","tomTat":"Trên Hồn đảo, Thạch Hạo cùng Cổ tổ Bát Tí Hồn tộc và Lão Thiên Thần Hồn tộc nướng thịt bốn Thiên Thần vừa bị giết, khiến các đệ tử Hồn tộc vừa thèm muốn vừa kinh sợ. Khi bàn về lần đột phá tiếp theo, Thạch Hạo cho biết mình cần Thánh Nhân mộc để đi con đường cực cảnh trọn vẹn nhất và từ chối dựa vào binh khí bảo cụ khi độ kiếp. Ba người sau đó mở quan tài ngọc; Đạo thư ngọc thạch mang theo tiên chủng tìm cách bỏ trốn nhưng bị tổ khí lò đá của Hồn tộc phong tỏa và thu phục. Kinh thư được chế từ thần ngọc năm màu, chứa truyền thừa vô thượng, song văn tự trên đó là Tiên văn nên không ai trong ba người có thể đọc. Bên ngoài Tiên cổ, các Giáo chủ thấy lối đi đã ổn định nên đưa nhóm Thiên Thần thứ hai tiến vào, trong khi Minh thổ, Tiên điện và Thiên quốc đều công khai mưu tính cách bắt giữ, hành hạ Thạch Hạo. Cuối chương, Thạch Hạo rời Hồn đảo tới vùng đất cổ xưa có Thánh Nhân mộc, bắt đầu chuẩn bị cho con đường đột phá có thể đưa hắn tới danh vị Thần vương."},{"chuong":978,"tieuDe":"Thánh Nhân Mộc","tomTat":"Thạch Hạo cùng Cổ tổ Bát Tí Hồn tộc đi sâu vào Tiên cổ tìm Thánh Nhân mộc để chuẩn bị đột phá Thần vương. Họ phát hiện Ninh Xuyên đã chiếm một rừng gồm bốn mươi chín cây và đang bế quan dưới sự bảo vệ của Mã Dược cùng Ma Lạc, khiến Thạch Hạo tức giận vì hai tộc từng nhận ân huệ của hắn. Trước khi rút lui, Thạch Hạo đấm nát nhiều ngọn núi để kinh động cổ thú, gây hỗn loạn quanh nơi Ninh Xuyên tu hành. Trong khi đó, Thiên Thần Tiên điện và Sát thần Thiên quốc công khai truy lùng hắn, còn các đại giáo thống nhất phải giết hắn trước khi trưởng thành. Sau nhiều lần không thể tiếp cận những khu rừng Thánh Nhân mộc khác, Thạch Hạo quyết định một mình tiến vào tuyệt địa rừng đá, nơi trường vực đặc biệt phong bế toàn bộ pháp lực. Hắn dùng thân thể chống lại kiến thần đen và rết có cánh kịch độc, rồi được Hoàng điệp thức tỉnh giúp đẩy lui hàng chục bộ lạc ác trùng. Cuối cùng, Thạch Hạo tìm thấy một rừng gồm mấy trăm cây Thánh Nhân mộc và tin rằng con đường đột phá của mình đã gần thành công."},{"chuong":979,"tieuDe":"Thánh Tế","tomTat":"Thạch Hạo tiến sâu vào rừng Thánh Nhân mộc, nơi pháp lực của hắn khôi phục, nhưng nhanh chóng bị ba Thiên Thần chồn tím điên truy sát và đâm thủng bả vai. Hắn dùng Súc địa thành thốn thoát thân, sau đó phát hiện trong hang ổ của đàn chồn còn có một con chồn già cấp Giáo chủ đang ngủ nên từ bỏ ý định đối đầu. Vài ngày sau, tàn trận dưới một đầm lầy phát ra gợn sóng khiến mọi sinh linh trầm miên, buộc đàn chồn tím phải trốn vào địa quật. Nhờ Vạn Linh đồ ngăn gợn sóng, Thạch Hạo nắm lấy cơ hội trở lại rừng và chuẩn bị bế quan. Hắn tu hành Chân nhất viễn cố trong nửa tháng, đạt Chân Thần đại viên mãn rồi giao việc hộ pháp cho Hoàng điệp và Đả Thần Thạch. Thạch Hạo rút tinh hoa Thánh Nhân mộc tế luyện đạo cùng thân thể, chính thức bắt đầu con đường Thánh tế đầy nguy hiểm. Quanh hắn xuất hiện ánh sáng phi tiên, tiên vụ, cung điện không tên và một con đường cổ thần bí từng khiến những nhân vật tuyệt đại biến mất khỏi thế gian."},{"chuong":980,"tieuDe":"Tiến Bộ Thần Tốc","tomTat":"Thạch Hạo bế quan trong rừng Thánh Nhân mộc và hoàn thành lần Thánh tế đầu tiên sau năm ngày, khiến thân thể cùng thần hồn được gột rửa nhưng vẫn quyết định chưa phá cảnh để tiếp tục hoàn thiện. Khi các Thiên Thần quấy phá bên ngoài tuyệt địa, hắn sai Đả Thần Thạch bố trí trận pháp kỳ trân kích nổ, đánh thức chồn tím cấp Giáo chủ và khiến một Thiên Thần bị chém lìa nửa người. Nửa tháng sau, Thạch Hạo trở lại rừng cây thực hiện lần Thánh tế thứ hai, đốt sạch thêm tỳ vết và làm thần hồn trở nên óng ánh hơn. Quá trình này khiến một con đường cổ thần bí hiện ra trong hư không, dẫn tới nơi vĩnh hằng chưa rõ tên. Bên ngoài, Thiên Thần Minh tộc, Ma Quỳ viên và Tiên điện phối hợp sử dụng ba loại pháp bảo phát ma âm nhằm khiến hắn tẩu hỏa nhập ma, nhưng ba luồng tiên khí đã giúp hắn chống chịu. Sau khi thề sẽ giết từng kẻ lúc xuất quan, Thạch Hạo quyết định bước lên con đường cổ để tìm hiểu đích đến của nó."},{"chuong":981,"tieuDe":"Con Đường Chín Đoạn","tomTat":"Thạch Hạo cùng Đả Thần Thạch và Hoàng điệp bước lên con đường đá cổ xuyên qua hư không, nơi hắn thoáng nhìn thấy một cặp mắt đỏ bí ẩn giữa bóng tối. Trong lúc đó, các Thiên Thần vẫn vây ngoài tuyệt địa, đánh trống và thổi kèn quấy nhiễu vì lo sợ tốc độ trưởng thành của hắn. Con đường bị chặt đứt thành chín đoạn, giữa mỗi đoạn là huyết quang và tia chớp đen đủ sức hủy diệt cốt khí Chân Thần, buộc Thạch Hạo dùng Nghịch long lân hộ thể để vượt qua. Sau chín lần xung kích khiến thân thể gần như giải thể, hắn dùng pháp của Liễu Thần khôi phục hoàn toàn. Cuối đường, các vách đá ép lại thành một nhà đá kín có dòng chữ cổ nói về việc đánh phá thiên địa để nhìn thấy Trường sinh. Thạch Hạo vận dụng nhiều bảo thuật và quyền pháp công phá vách đá, làm lộ ra hơn mười thi thể không hồn nhưng vẫn còn sinh cơ. Những vết rách tỏa thánh quang sau lưng các thi thể khiến Đả Thần Thạch liên tưởng đến ghi chép về phi thăng, còn Thạch Hạo nghi ngờ đây là xác lột của những người đã thành Tiên."},{"chuong":982,"tieuDe":"Không Muốn Phi Thăng","tomTat":"Thạch Hạo đánh nứt vách đá cuối con đường cổ nhưng lập tức bị một lực hút khổng lồ kéo nguyên thần rời khỏi thân thể. Hắn vận dụng Nguyên thủy chân giải, cốt văn và pháp của Liễu Thần để trấn áp nguyên thần, kiên quyết từ chối con đường phi thăng buộc mình phải bỏ lại thể xác và người thân. Trong quá trình chống cự, hắn phát hiện phía sau vách đá tồn tại khí tức tương tự Linh giới và Hư Thần giới nhưng nồng đậm hơn vô số lần, từ đó quyết định sau này sẽ tìm hiểu nguồn gốc của Linh giới. Thạch Hạo mang Đả Thần Thạch và Hoàng điệp trở lại khu rừng Thánh Nhân mộc, không đụng tới những thi thể lột xác để tránh tạo nhân quả. Tại đây, hắn dùng chính thân thể làm tế phẩm trong quá trình Thánh tế, nhiều lần bị đạo ngân và pháp tắc đánh rớt cảnh giới rồi tự mình khôi phục. Dù Thiên Hồ tộc, Minh tộc, Ma Quỳ viên và Tiên điện liên tục quấy phá, hắn vẫn hoàn thành lần bế quan thứ mười, chính thức bước vào cảnh giới Thánh tế và đạt chiến lực có thể đối đầu Thiên Thần. Sau khi đột phá, hắn cân nhắc giữa việc ra ngoài thanh toán kẻ địch và đi lấy Lôi Kiếp dịch."},{"chuong":983,"tieuDe":"Xuất Quan","tomTat":"Thạch Hạo đột phá thành công lên Thánh tế, nhất thời có sức chiến đấu cấp Thiên Thần nhưng suýt lạc lối vì di chứng khi đại đạo vừa thành. Sau nửa tháng quan sát, hắn phát hiện tu vi mới dao động theo chu kỳ: trạng thái cực thịnh kéo dài từ hai đến bốn ngày rồi chuyển sang thời kỳ suy kiệt với độ dài tương đương. Hắn tiếp tục hấp thu hào quang của những cây Thánh Nhân mộc gần đó để gột rửa thân thể và linh hồn, chờ đúng lúc sức mạnh phục hồi tới đỉnh cao mới xuất quan. Bên ngoài tuyệt địa, Thiên Thần giáp bạc giả vờ chiêu mộ hắn trong khi bí mật mở tế đàn gọi viện binh, còn Thiên Thần giáp xanh phối hợp dẫn thần thủy Thái âm tới nhằm hủy diệt tiểu thiên thế giới. Thạch Hạo nhìn thấu âm mưu, khóa chặt thiên địa, ép thần thủy chảy ngược và vận dụng chân thân cùng linh thân để đồng thời chặn hai đối thủ. Hắn đập nát hồ lô xanh, chặt đầu Thiên Thần giáp xanh, giết Thiên Thần giáp bạc rồi tiêu diệt luôn hai Thiên Thần vừa đến cứu viện. Sau khi bốn Thiên Thần đều bỏ mạng, Thạch Hạo tuyên bố sẽ giết sạch Thiên Thần của Tiên điện và Minh tộc, báo hiệu một trận chấn động lớn sắp nổi lên trong Tiên cổ."},{"chuong":984,"tieuDe":"Thần Vương Quật Khởi","tomTat":"Sau khi xuất quan và âm thầm giết bốn đại Thiên Thần, Thạch Hạo tìm đến cổ địa của Ninh Xuyên nhưng phát hiện đối thủ đã rời đi, rất có thể đã tiến vào lĩnh vực Thánh tế. Hắn tới Hàn giới, gặp người cậu của Nguyệt Thiền và cố tình dùng chuyện của nàng để khiêu khích, dẫn đến một trận giao chiến mà Thạch Hạo giành thắng lợi và phá hỏng Tứ tượng tháp. Sau khi biết thân phận đối phương, hắn không giết mà xé không gian ném người này đi. Thạch Hạo tiếp tục lặn xuống hồ Thái âm, phá trận pháp và lấy được đá Thái âm bản nguyên, dự định trao chí bảo này cho Thái Âm Ngọc Thỏ. Tiếp đó, hắn công khai giết ba Thiên Thần rồi truy sát Thiên Thần Minh tộc, đồng thời hạ thêm bốn Thiên Thần tới cản đường. Cuối cùng, Thạch Hạo đánh tan thân thể, chặt đứt minh cốt và diệt nguyên thần của đối thủ. Hắn ném đầu lâu Thiên Thần Minh tộc ra ngoài Tiên cổ, công khai tuyên bố sẽ giết mọi Thiên Thần được các Giáo chủ đối địch phái vào."},{"chuong":985,"tieuDe":"Chửi Bới Giáo Chủ","tomTat":"Thạch Hạo chặn lối vào giới bích Tiên cổ, ném trả đầu lâu một Thiên Thần Minh tộc và công khai chửi bới các Giáo chủ đang tụ tập bên ngoài. Minh chủ phóng Minh diễm rồi hợp lực với những Giáo chủ khác công kích giới bích, nhưng quy tắc chí cường vẫn ngăn họ mở đường tiến vào. Một Thiên Thần Thiên Nhân tộc nhận ra kẻ khiêu khích rất có thể là Hoang, khiến Thạch Hạo nhớ lại mối hận bị giam trong Hắc lao Thiên Chi Thành và quyết tâm tử chiến với bộ tộc này. Trùng vương của Minh tộc đưa linh thân vào Tiên cổ, dùng vảy giáp cùng chí độc giao chiến nhưng bị Thạch Hạo đánh vỡ phòng ngự và bóp nổ thành mưa máu. Dư độc khiến Thạch Hạo hơi choáng váng, song Bảo thuật Liễu Thần lập tức giúp hắn phục hồi sức sống. Hắn tiếp tục án ngữ lối vào, giết sạch những Thiên Thần và đệ tử được đưa tới truyền tin. Trước sự bất lực của các Giáo chủ, có người đề nghị nhờ những Thiên Thần trẻ tuổi đã tu ra tiên khí đối phó hắn. Thạch Hạo cuối cùng tuyên bố sẽ quét sạch toàn bộ Tiên cổ rồi đứng dậy chuẩn bị xuất kích."},{"chuong":986,"tieuDe":"Ngày Tận Thế","tomTat":"Thạch Hạo để ba bộ linh thân canh lối ra rồi dùng chân thân quay vào sâu trong Tiên cổ, nhờ Bát Tí Hồn tộc thu thập tình báo và bắt đầu truy sát các Thiên Thần. Hắn lần lượt giết hung cầm Hỏa Vân động, giao long Yêu Long đạo môn và Thiên Thần Ma Quỳ viên, đồng thời thu Chân vũ, thi thể các con mồi cùng một nửa số hạt kết tinh khí huyết Thiên Thần. Cổ tổ Ngân Huyết ma thụ bất ngờ tập kích để trả thù nhưng Thạch Hạo dùng Phá Giới phù thoát thân, còn cổ tổ Bát Tí Hồn tộc ra mặt nghênh chiến. Nhận được tin Thiên Thần Tiên điện đang trốn về lối ra, Thạch Hạo lập tức truy đuổi và hợp lực với ba bộ linh thân chặn đánh. Dù thi triển tuyệt học cấm kỵ Nhân Tiên ấn và thiêu đốt bí pháp tháo chạy, Thiên Thần Tiên điện vẫn bị cành liễu hóa chiến mâu xuyên sọ, đánh nát nguyên thần. Cuộc tàn sát kết thúc với toàn bộ Thiên Thần trọng yếu tiến vào Tiên cổ bị quét sạch, khiến ngày này được gọi là Ngày tận thế."},{"chuong":987,"tieuDe":"Thái Độ Của Các Phương","tomTat":"Thạch Hạo kéo thi thể Thiên Thần Tiên điện trở lại Tiên cổ, ném đầu lâu ra ngoài giới bích và công khai sỉ nhục Tiên điện cùng Minh tộc, khiến thượng giới chấn động. Tiên điện, Thiên quốc, Minh tộc, Thiên Nhân tộc và nhiều đại giáo đồng loạt quyết tâm diệt hắn; nhân vật số hai Tiên điện trực tiếp tuyên án, còn một cường giả khủng bố ngủ từ thời Thái cổ có dấu hiệu thức tỉnh. Thanh Y, Nguyệt Thiền và Vân Hi có những phản ứng phức tạp trước sự quật khởi của Thạch Hạo, trong khi Tam Thạch Thiên quân lộ diện bên Vân Hi và thừa nhận thực lực của hắn vượt xa các thiên tài cổ đại mình từng gặp. Thạch Hạo tiếp tục quét ngang Tiên cổ, đánh gục nhiều Thiên Thần rồi thu lại linh thân khi thời hạn sắp hết. Sau đó, hắn tới Hồn đảo thỉnh giáo cổ tổ và lão Thiên Thần Bát Tí Hồn tộc về việc chuẩn bị độ Thiên kiếp mạnh nhất. Bát Tí Hồn tộc âm thầm liên lạc lực lượng hộ pháp, vừa kỳ vọng lần độ kiếp sẽ giúp hóa giải nguyền rủa vừa lo Thạch Hạo không thể sống sót qua thiên kiếp."},{"chuong":988,"tieuDe":"Thần Vương Kiếp","tomTat":"Lôi đình khổng lồ bùng nổ trong một tiểu thiên thế giới khiến quần hùng Tiên cổ ban đầu tưởng ngoại giới tấn công, sau đó nhận ra có người đang độ Thần vương kiếp. Người độ kiếp là Thạch Hạo, đang đối mặt với kiếp nạn đặc thù của cảnh giới Thánh tế, nơi thành công có thể trở thành Thần vương còn thất bại sẽ rơi xuống Thần Hỏa cảnh. Ở tầng đầu tiên, hắn dùng ba luồng tiên khí và bảo thuật chí cường tiêu diệt đàn kim ô lôi đình mang khí tức Thiên Thần cấp. Thạch Hạo tiếp tục triển khai Liễu Thần pháp cùng nhiều bảo thuật, vượt qua các tầng thứ hai đến thứ năm dù chiến y tan nát và xương cốt gãy vỡ. Tại tầng sáu, hắn giết mười kỵ sĩ lôi đình và thu phục một con Thiên mã, rồi bị chém lìa ngang hông ở tầng bảy nhưng vẫn cưỡng ép ngưng tụ lại thân thể để vượt qua. Vân Hi và Nguyệt Thiền đều xuất hiện quan sát, mỗi người mang tâm trạng riêng trước phong thái và thành tựu của Thạch Hạo. Khi chương kết thúc, hắn đã tiến vào tầng thứ tám với tốc độ khiến mọi người kinh ngạc, trong khi tầng thứ chín được cảnh báo sẽ là đại kiếp nạn quyết định sống chết."},{"chuong":989,"tieuDe":"Tầng Trời Thứ Tám, Thứ Chín","tomTat":"Thạch Hạo tiến vào tầng thứ tám của Thần vương kiếp và bị một xương sọ khổng lồ nuốt vào, hóa thành lò luyện tập trung toàn bộ lôi đình để hủy diệt hắn. Thân thể cùng nguyên thần liên tục tan vỡ, nhưng hắn dùng Nguyên thủy chân giải, pháp của Liễu Thần và cốt văn để chữa trị, tái tụ. Sau mười lần xung kích, hắn vận chuyển Bát Cửu Thiên Công dung hợp toàn bộ bảo thuật, đánh thủng lò xương sọ và thoát ra trong trạng thái trọng thương. Một Thiên Thần nhân cơ hội ném bí bảo vào lôi kiếp đánh lén, song Thạch Hạo né được, còn kẻ tập kích phải dùng Tế Tử phù để thoát khỏi lôi đình bổ ngược. Thạch Hạo hồi phục rồi bước lên tầng thứ chín, nơi thiên kiếp bất ngờ ép đạo hạnh của hắn từ mức ngang Thiên Thần xuống Chân Thần rồi Thần Hỏa cảnh. Năm Thiên Thần ngoại giới lập tức xông vào lôi đình đánh giết, trong khi Bát Tí Hồn tộc định cứu viện lại bị các cường giả bản địa ngăn cản. Tình thế của Thạch Hạo trở nên vô cùng nguy cấp, khiến Vân Hi, Nguyệt Thiền và quần hùng đều đặc biệt chú ý."},{"chuong":990,"tieuDe":"Kiếp Thành","tomTat":"Năm Thiên Thần ngoại giới lợi dụng lúc tu vi Thạch Hạo rơi xuống Thần Hỏa cảnh để truy sát hắn giữa lôi kiếp, khiến hắn trọng thương và suýt mất mạng. Việc trực tiếp can thiệp khiến chúng bị thiên kiếp tính là người tham dự, trong đó kẻ ra tay nhiều nhất bị thiên phạt cấp Thiên Thần đánh nổ tung. Pháp lực Thạch Hạo sau đó phục hồi về lĩnh vực Thánh tế, giúp hắn phân ra ba linh thân và dùng Luân Hồi, Côn Bằng pháp, Bảo thuật Lôi Đế, Động thiên duy nhất cùng Bát Cửu Thiên Công tiêu diệt bốn kẻ còn lại. Vượt qua tầng thứ chín, hắn tiến vào tầng thứ mười có cảnh tượng như tiên cảnh nhưng phải đi vòng qua Trảm Tiên đài vì sát khí quá mạnh. Thạch Hạo cuối cùng tìm thấy Tiên trì chứa Lôi Kiếp dịch năm màu, uống thử và quét sạch toàn bộ ám thương, qua đó xác nhận thiên kiếp đã hoàn thành. Thần dịch cứu mạng khiến các Thiên Thần bản địa và Bát Tí Hồn tộc nóng lòng bày tỏ thiện ý, trong khi Mã Dược cùng Ma Lạc hối hận và không cam lòng."},{"chuong":991,"tieuDe":"Bảo Dịch Phong Ba","tomTat":"Thạch Hạo uống Lôi Kiếp dịch năm màu trong tiên trì, phục hồi hoàn toàn thân thể và nguyên thần, xóa bỏ ám thương rồi ổn định lĩnh vực Thánh tế sau Thần vương kiếp. Sự quật khởi của hắn khiến Vân Hi tiếc nuối lựa chọn của Thiên Nhân tộc, còn người cậu của Nguyệt Thiền muốn dùng quan hệ giữa hai người để lôi kéo hắn vào Bổ Thiên giáo. Khi Thạch Hạo ngừng uống để giữ lại bảo dịch, Chậu Tụ Bảo bất ngờ xuất hiện và tìm cách hút Lôi Kiếp dịch khỏi tiên trì, buộc hắn lập tức phong ấn nơi này. Cổ tổ Bát Tí Hồn tộc vạch ra Ngân Huyết ma thụ tộc là kẻ đứng sau, trong khi Giáo chủ của tộc này hiện thân và lấy danh nghĩa hóa giải nguyền rủa để ép Thạch Hạo chia đều bảo dịch. Thạch Hạo tuyên bố sẽ tặng bảo dịch cho dân bản địa nhưng tuyệt đối không cho Ngân Huyết ma thụ tộc một giọt, sau đó mang lôi hải đến cổ địa của họ và dẫn thiên kiếp đánh xuống lãnh địa. Trước lời đe dọa của đối phương, hắn công khai treo thưởng Lôi Kiếp dịch cho bất kỳ bộ tộc nào giết được Giáo chủ Ngân Huyết ma thụ tộc."},{"chuong":992,"tieuDe":"Quần Hùng Chào Đón","tomTat":"Cổ tổ Bát Tí Hồn tộc và cổ tổ Mỹ Nhân tộc liên thủ truy kích cổ tổ Ngân Huyết ma thụ tộc, đánh hắn trọng thương đến mức khó tái chiến trong một hai năm. Trong tầng thứ mười của lôi kiếp, Thạch Hạo dẫn thiên kiếp giết hai Thiên Thần Ngân Huyết ma thụ rồi san bằng toàn bộ cổ địa của tộc này, nhưng không truy sát những tộc nhân đã bỏ trốn. Hắn thu Lôi Kiếp dịch năm màu và trao cho hai Giáo chủ đồng minh, giúp họ hóa giải nguyền rủa Tiên cổ và khôi phục sức mạnh. Thạch Hạo tiếp tục phân phát bảo dịch cho các Giáo chủ, Thiên Thần và Chân Thần thuộc những tộc từng bảo vệ mình, đồng thời cứu tỉnh thêm hai Giáo chủ đã đần độn lâu năm. Nhờ đó, quanh hắn hình thành một liên minh gồm bốn Giáo chủ cùng nhiều Thiên Thần, đủ sức chuẩn bị đối phó nguy cơ chí cường giả ngoại giới tiến vào qua vết rách Tiên cổ. Trái lại, Nhân Mã tộc và Cổ Ma tộc bị từ chối vì Mã Dược cùng Ma Lạc từng chặn giết Thạch Hạo; sau khi lên tiếng phản đối, hai người bị các Thiên Thần truy sát và phải tháo chạy."},{"chuong":993,"tieuDe":"Bão Táp","tomTat":"Khả năng hóa giải nguyền rủa của Lôi Kiếp dịch khiến các tộc bản địa Tiên cổ tranh nhau tiếp cận Thạch Hạo, nhưng hắn hiểu liên minh này không bền nên dùng phần thần dịch còn lại treo thưởng lấy đầu Mã Dược và Ma Lạc. Hai Thiên Thần tìm tới những cổ địa thù địch, đánh thức các Giáo chủ và vận động phe Ninh Xuyên nhằm chống lại Hoang. Cổ tổ Bát Tí Hồn tộc đánh tan linh thân của một Giáo chủ, còn chân thân kẻ ấy tập kích Hồn đảo nhưng bị ba Giáo chủ vây đánh đến mức mất một cánh tay mới thoát. Sau đó cổ tổ Bát Tí Hồn tộc đánh nát thân thể Mã Dược và Ma Lạc từ xa, để các Thiên Thần khác kết liễu và mang đầu họ về đổi Lôi Kiếp dịch. Uy thế của Thạch Hạo khiến Cô Kiếm Vân lập tức rút khỏi Tiên cổ, trong khi lối ra bị phong tỏa để ngăn Ninh Xuyên chạy thoát. Trước nguy cơ các Giáo chủ tiếp tục tập kích, Thạch Hạo định rời Hồn đảo để tìm Thiên Thần thụ, động phủ tiên gia và Bạch Quy Đà Tiên; hắn cũng biết bốn cây Thiên Thần thụ vốn là một tiên dược bị tách rời và có thể hợp nhất thành Trường Sinh dược. Khi tin Ninh Xuyên đang bị nhiều Thiên Thần truy sát truyền tới, Thạch Hạo quyết định ưu tiên tiêu diệt đối thủ, khiến toàn Tiên cổ chấn động."},{"chuong":994,"tieuDe":"Cổ Địa","tomTat":"Tin Ninh Xuyên suy yếu sau khi dùng Thánh Nhân mộc tiến vào lĩnh vực Thánh tế lan khắp Tiên cổ, khiến Thạch Hạo quyết định lên đường truy sát. Ninh Xuyên cố ý để lộ tung tích tại Thanh Linh giới, phối hợp với ba Giáo chủ lấy mình làm mồi nhử nhằm tập sát đối thủ. Nhờ lời cảnh báo của cổ tổ Mỹ Nhân tộc, Thạch Hạo bí mật chuẩn bị tổng cộng năm Giáo chủ hộ tống, buộc phe phục kích phải đưa Ninh Xuyên tháo chạy. Không thể diệt đối thủ, Thạch Hạo chuyển sang tìm cơ duyên đã định và một mình vượt qua sa mạc bão cát, vết nứt hư không, hỏa tinh Thái dương cùng vùng lôi điện mang thuộc tính thiên kiếp. Sau hai ngày tiến sâu vào cổ địa và chứng kiến nhiều bột xương Thiên Thần, hắn lên tới đỉnh núi. Tại đây, Thạch Hạo tìm thấy Thiên Thần thụ cổ xưa đang nở hoa và đã kết một số Thiên Thần quả phát sáng."},{"chuong":995,"tieuDe":"Thiên Thần Thụ","tomTat":"Thạch Hạo tới đỉnh núi và gặp Thiên Thần thụ, một cổ thụ hoàng kim có linh trí đã đạt Thiên Thần đỉnh cao nhưng bị thiên địa áp chế. Cổ thụ định tặng hắn một Thiên Thần quả chín có thể giúp lập tức thành tựu Thiên Thần, song hắn không muốn dựa vào ngoại vật để đột phá thiếu vững chắc hoặc bỏ lỡ cơ hội dùng lôi kiếp rèn thân. Sau khi kiểm tra thân thể, nguyên thần và nhìn thấy ba luồng tiên khí của Thạch Hạo, Thiên Thần thụ thay đổi thái độ, cân nhắc cùng hắn rời Tiên cổ. Cổ thụ cho biết cần Vạn Vật thổ để thu nhỏ còn một thước mà vẫn sinh trưởng, tăng tiến đạo hạnh và tiếp tục kết quả. Thạch Hạo vì muốn đưa cây về giúp người thân tại Thạch thôn nên tiến sâu vào cổ địa tìm thần thổ. Hắn vượt qua vùng lôi đình và cây cầu đá, dù bị sét đánh cháy đen vẫn tới được vùng tinh thổ thần bí. Tại đó, Vạn Vật thổ tỏa hào quang như mặt kính và chiếu hiện bóng một thiếu nữ khiến hắn cảm thấy vô cùng quen thuộc."},{"chuong":996,"tieuDe":"Ma Nữ","tomTat":"Trong một vùng tịnh thổ đầy cổ dược và thánh dược, Thạch Hạo phát hiện bóng người bên dưới lớp Vạn Vật thổ nên triển khai Động thiên duy nhất rồi thận trọng đào xuống. Hắn tìm thấy một thiếu nữ mặc giáp trụ Kim Ô, nhưng tàn trận quanh nàng vẫn phóng kiếm quang chém bị thương vai hắn. Khi cô gái tỉnh lại và dùng tiên khí cùng thạch châu chống trả, Thạch Hạo nhận ra nàng chính là Ma nữ của Tiệt Thiên giáo. Ma nữ tiết lộ thân thể hiện tại mới là chân thân, còn những lần gặp trước tại Côn Bằng sào, đế đô Thạch quốc và trong vụ bắt Nguyệt Thiền đều chỉ là linh thân. Hai người hợp sức thu Vạn Vật thổ nhưng chỉ lấy được khoảng bảy phần mười vì một sức mạnh kỳ dị giữ chặt phần còn lại. Sau khi lớp đất mỏng đi, đường nét của một sinh linh khác xuất hiện ở tầng sâu. Ma nữ còn cho biết nàng đến đây vì truy đuổi Thiên địa mẫu khí đỉnh và xác nhận chiếc đỉnh đang nằm ngay dưới chân họ, khiến Thạch Hạo liên tưởng tới bí ẩn từng thấy ở Táng giới."},{"chuong":997,"tieuDe":"Một Giọt Đế Huyết","tomTat":"Thạch Hạo hội ngộ Ma nữ tại vùng Vạn Vật thổ, đấu khẩu với nàng quanh chuyện Nguyệt Thiền rồi cùng bắt tay đào bới. Hai người tìm thấy một bộ chiến y nứt vỡ từng thuộc về một cô gái đặt chân vào Tiên đạo; Thạch Hạo lấy thần thổ còn Ma nữ nhận chiến y. Dưới đáy khu đất, họ phát hiện một giọt máu đỏ tươi được hỗn độn và pháp tắc bao phủ, mang uy áp đủ áp chế sinh linh dưới cấp Thiên Thần. Thiên Nhãn thông của Thạch Hạo không thể nhìn thấu giọt máu, còn Ma nữ nhận ra nó giống loại máu từng bám trên Thiên địa mẫu khí đỉnh. Nàng kể chiếc đỉnh và bóng người đi cùng từng xuất hiện giữa những mảnh vỡ thời gian, có dấu hiệu vượt qua cổ kim. Khi Thạch Hạo chất vấn mục đích của giọt máu, nó lập tức dâng trào khí tức, làm hư không rách lìa và truyền ra âm thanh chinh chiến. Một chàng trai mang thân phận Thiên Đế hiện lên mơ hồ trước Thạch Hạo, trong khi chính hắn cũng tự phát tỏa ra khí thế khó hiểu khiến Ma nữ bị đẩy lùi."},{"chuong":998,"tieuDe":"Không Tồn Tại Trong Thiên Địa","tomTat":"Giọt Đế huyết tái hiện một dấu ấn vượt qua thời gian, trong đó Thạch Hạo nhìn thấy chàng trai bí ẩn dưới chiếc đỉnh cố truyền đạt một cảnh báo trọng yếu nhưng không thể mở miệng. Cảnh tượng tiếp tục cho thấy người ngồi quay lưng với chúng sinh, một nữ Đế và đạo sĩ trung niên giống Tào Vũ Sinh hợp lực đưa chiếc đỉnh vào con đường phủ đầy mảnh vỡ thời gian, giữa hình ảnh Cửu thiên Thập địa nhuốm máu. Khi dấu ấn tan biến, Thạch Hạo làm theo đề nghị của Ma nữ, dùng Vạn Vật thổ trong cốt đỉnh thu lấy giọt Đế huyết. Hai người hái thêm thánh dược rồi vượt lôi điện rời cổ địa; trên đường, Thạch Hạo dùng Liễu Thần pháp chữa thương và để lộ ba luồng tiên khí. Trở lại chỗ Thiên Thần thụ, hắn đưa cốt đỉnh ra để cây thu nhỏ, tiến vào trong và cắm rễ trong Vạn Vật thổ. Sau khi biết các Giáo chủ ngoại giới gần đánh tan Tiên cổ, Thạch Hạo quyết định chuẩn bị rời đi dù hiểu rằng một cuộc truy sát dữ dội đang chờ mình. Cùng lúc đó, bên ngoài Tiên cổ, một Thiên Thần trẻ tuổi thuộc nhóm khách thần bí liên tiếp đánh bại cường giả ba ngàn châu và chờ Lục Quan vương, Trích tiên hoặc Hoang ra ứng chiến."},{"chuong":999,"tieuDe":"Cửu Thiên Thập Địa","tomTat":"Kiếm vương Mục Thiết tung kiếm quang chấn động Thương châu nhưng nhanh chóng bị khách vực ngoại đánh gãy thiết kiếm và trọng thương, cho thấy Thiên Thần hàng đầu bản địa vẫn không thể chống lại đối phương. Lâm Thiên cùng các Thiên Thần trẻ tuổi vực ngoại công khai coi thường Ba ngàn châu, trong khi tu sĩ bản địa đặt hy vọng vào Diệp công tử, Thạch Hạo và Trích Tiên. Những người trung niên đi cùng nhóm khách tiết lộ cổ giới hoàn chỉnh đã bị đại chiến kỷ nguyên Tiên cổ đánh nát thành Cửu Thiên Thập Địa, còn Ba ngàn đạo châu chỉ là một thế giới thuộc Thập Địa. Ba ngàn đạo châu từng cùng các chí tôn dùng ba ngàn đạo tắc trấn áp Biên Hoang, nhưng hiện đã suy tàn nghiêm trọng. Kẻ địch từng giết Trường Sinh giả và Chân Tiên có thể trở lại, khiến Biên Hoang trở thành nơi được dự báo sẽ mở đầu đại kiếp. Để ứng phó, nhiều thế giới đang mở truyền tống trận cổ, triệu tập Giáo chủ chí cường và chuẩn bị tuyển những Thiên Thần trẻ tuổi ưu tú vào Thư viện Thiên Thần, Thánh viện cùng các học phủ khác. Nhóm Lâm Thiên hiện chỉ có nhiệm vụ ước lượng thực lực Ba ngàn đạo châu, còn những thiên tài mạnh nhất của toàn Cửu Thiên Thập Địa vẫn chưa xuất hiện."},{"chuong":1000,"tieuDe":"Cướp Lôi Kiếp Dịch","tomTat":"Thạch Hạo đồng hành với Ma nữ qua Di địa Tiên cổ, khiến các sinh linh dọc đường sợ hãi né tránh vì uy danh giết Thiên Thần và ăn nhiều di chủng mạnh. Trước việc khe nứt hư không ngày càng mở rộng, hắn trở lại Hồn đảo triệu tập những người thân quen, đồng thời thuyết phục năm đại Giáo chủ hộ pháp để thử độ Thần vương kiếp lần nữa và chiêu mộ thêm lực lượng. Thạch Hạo vượt qua thiên kiếp trong lĩnh vực Thánh tế nhưng Lôi trì không xuất hiện, qua đó hiểu rằng mỗi cảnh giới chỉ được trời xanh ban Lôi Kiếp dịch một lần. Dù không thu được thần dịch, khả năng liên tục vượt kiếp của hắn vẫn khiến các Giáo chủ được mời chấp nhận gia nhập phe mình. Biết Ninh Xuyên cũng đang độ kiếp dưới sự bảo vệ của phe Ngân Huyết ma thụ, Thạch Hạo lập tức dẫn các Giáo chủ tới tập kích. Hắn bất chấp thương thế xông vào biển sét, giao chiến với Ninh Xuyên và dùng một chiếc đỉnh đoạt được một phần Lôi Kiếp dịch. Ninh Xuyên nổi giận tiếp tục tử chiến với Thạch Hạo giữa thiên kiếp, khiến cuộc đối đầu vẫn chưa kết thúc."}];
